const a={lang:"xh",source:"src/constants/lessonData.js",lessons:71,hash:{1:"80c0d50a",2:"7a0ec9a6",3:"5e407f05",4:"c9cd9cb3",5:"5c610420",6:"b4a6b648",7:"d66596d0",8:"796196ca",9:"6c2a6709",10:"8cdd1852",11:"747d9b20",12:"5b50c1ca",13:"5dd950f1",14:"de4e5bbf",15:"5db03e62",16:"820d4185",17:"d3349e94",18:"f7903ca3",19:"4fd21613",20:"cb2b025c",21:"392f93bc",22:"846dbcdf",23:"70df8bf3",24:"318d2051",25:"7dc72b96",26:"e338834b",27:"a5f9340e",28:"650ed568",29:"1d51c7b0",30:"29dba498",31:"390a64a0",32:"424ee5ad",33:"4d7d49b0",34:"fb5f9b39",35:"c5bdaa40",36:"e09ff28e",37:"c48e70c0",38:"eb1e4f5a",39:"881a67f4",40:"bf4399f2",41:"c4f52986",42:"551af277",43:"d87240fc",44:"2b7b683e",45:"a3dd8868",46:"7873826b",47:"0ba85d7e",48:"6d2df7b4",49:"c1055330",50:"789af852",51:"27e927d2",52:"041c444d",53:"8fb1d4bc",54:"2352615a",55:"b7571fb2",56:"f20ea6ce",57:"736fbba1",58:"d6965200",59:"c736a610",60:"6db8d44d",61:"eec64988",62:"0171d5b9",63:"606ebf4a",64:"70769bc6",65:"94423ba8",66:"e27a40f2",67:"8c29d099",68:"5ce307ea",69:"91203966",70:"c07c9a34",71:"3605b239"}},i=JSON.parse(`{"1":{"title":"Yintoni iSabelo?","desc":"Yiba ngumnini wesuntswana lenkampani","content":"Khawufane ucinge: wena nabahlobo abali-9 nifaka {c}10 ngamnye ukuze nithenge iitekkies ze-{c}100 kunye. Ngamnye kuni ungumnini we-1/10 yezo tekkies, kwaye leyo, ngokusisiseko, yisabelo! Xa uthenga isabelo kwa-{retail}, uba ngumnini wesuntswana levenkile nganye, lemveliso nganye, nayo yonke {cName} abayenzayo. Okukhona inkampani ikhula, kokukhona isabelo sakho sixabiseka ngakumbi! 🔥","quiz":{"q":"Wena nabahlobo aba-4 nahlulelana ngokulinganayo iindleko zesitulo sokudlala se-{c}500. Ngamnye kuni ungumnini wantoni?","options":["1/5 (20%) yesitulo umntu ngamnye","Akukho nto, ngumntu omnye kuphela onokuba ngumnini waso","Isitulo siphela kunye, kungekho sabelo somntu ngamnye"]}},"2":{"title":"I-{ex} Ichaziwe","desc":"Iqonga lezabelo lase{name}","content":"Cinga nge-{ex} ({exFull}) njengemarike enkulu ekwi-intanethi, kodwa endaweni yokuthenga iitekkies okanye iifowuni, abantu bathenga baze bathengise amasuntswana (izabelo) eenkampani ezifana no-{top5}. Ivulekile yonke imihla yeveki ngaphandle kweeholide zikawonke-wonke, kwaye amaxabiso ayatshintsha imini yonke ngokuxhomekeke kubantu abathengayo nabathengisayo. I-{ex} {exDesc}! 🌍","quiz":{"q":"I-{ex} ifana nantoni kakhulu?","options":["Iakhawunti yokonga imali ebhankini","I-app yemali yeselula","Imarike apho uthenga uze uthengise khona amasuntswana eenkampani"]}},"3":{"title":"Iinkunzi neeBhere","desc":"Iindlela imarike ehamba ngazo, zicaciswa","content":"Kwiimarike, zizilwanyana eziqhuba izinto 😄\\n\\n🐂 Inkunzi = amaxabiso ANYUKAYO. Cinga ngenkunzi ehlaba ngeempondo isiya phezulu. Wonke umntu uyaphumelela, abantu bayathenga, imeko intle.\\n\\n🐻 Ibhere = amaxabiso AYEHLAYO. Cinga ngebhere ebetha ngentende isiya ezantsi. Abantu boyika, bayathengisa, ayilotyeli lilungileyo.\\n\\nXa umntu esithi 'ndi-bullish nge-{tech}', ucinga ukuba ixabiso liza kunyuka. Xa esithi 'ndi-bearish', ucinga ukuba liya ezantsi. Uza kuwava la magama yonke indawo kwezemali!","quiz":{"q":"Umhlobo wakho uthi: 'Ndi-bearish nge-{telco} kule veki.' Kuthetha ntoni oko?","options":["Ucinga ukuba ixabiso lika-{telco} liza kunyuka","Ucinga ukuba ixabiso lika-{telco} liza kwehla","Ufuna ukuthenga u-{telco} omninzi kangangoko"]}},"4":{"title":"Yintoni iBhrokha?","desc":"Isango lakho lokuthenga izabelo","content":"Awunakuvele ungene kwa-{retail} uthi 'ndicela undinike inxalenye yenkampani yakho' 😂 Ufuna ibhrokha: i-app okanye inkonzo edibanisa abathengi nabathengisi kwiqonga lezabelo.\\n\\nCinga ngebhrokha njenge-{shop}. Ufuna into, i-{shop} ikudibanisa nayo. Yona iqhuba intengiselwano ize ibize umrhumo omncinci. Iibhrokha ezidumileyo e{name} ziquka u-{broker} nezinye.\\n\\nNantsi into ibhrokha ENGAYENZIYO: ukugqiba ukuba zeziphi izabelo eziya kunyuka. Yona idlulisela umyalelo wakho emarikeni. Ixabiso lishukuma ngenxa yoko kuthengwa nokuthengiswa ngabantu bonke phaya, kungekhona ngenxa yokuba ibhrokha yakho itshilo.\\n\\nNoko ke, iibhrokha ziyazipapasha izimvo zazo. Abahlalutyi bazo banika izabelo isigqibo sokuthi 'thenga', 'bamba' okanye 'thengisa'. Uluvo ayingomyalelo 🤷 Abahlalutyi bayaphikisana ngokuphandle omnye nomnye ngesabelo esinye kanye, kwaye abaninzi kubo baphela bengachananga. Funda isigqibo sabo njengoluvo, kungekhona njengomthetho.\\n\\nI-NoobTrader ikufundisa kanye indlela oku okusebenza ngayo, simahla, ngemali yokuzilolonga!","quiz":{"q":"Kutheni ufuna ibhrokha ukuze uthenge izabelo?","options":["Iibhrokha zigqiba ukuba zeziphi izabelo eziya kunyuka","Kufuneka uzihlawule ngaphambi kokuba ufumane imali","Zidibanisa abathengi nabathengisi kwiqonga lezabelo"]}},"5":{"title":"Izisekelo zeXabiso leSabelo","desc":"Kutheni amaxabiso enyuka aze ehle?","content":"Wakhe waqaphela indlela iitekkies ezikhutshwe zambalwa ezinyuka ngayo ixabiso xa ziphuma? Kwenzeka into efanayo kwizabelo. Konke kusekuboneleleni nakwimfuno.\\n\\n📈 Abantu abaninzi BAFUNA ukuthenga → ixabiso LIYANYUKA\\n📉 Abantu abaninzi BAFUNA ukuthengisa → ixabiso LIYEHLA\\n\\nUkuba u-{telco} ubhengeza ukuba ufumana abathengi abatsha abazizigidi ezili-10, wonke umntu ufuna isuntswana, ngoko ixabiso liyadubula. Ukuba banika ingxelo yelahleko enkulu, abantu bathengisa bengcangcazela, ngoko ixabiso liyehla. Iindaba, iziphumo, kwanezinto ezitrendayo kwi-social media zinokushukumisa amaxabiso ezabelo ngoko nangoko!","quiz":{"q":"U-{retail} ubhengeza inzuzo ephakame ngaphezu kwazo zonke kunye nezicwangciso zokuvula iivenkile ezintsha ezingama-50. Kwenzeka ntoni mhlawumbi kwixabiso lesabelo sabo?","options":["Liyanyuka njengoko abantu abaninzi befuna ukuthenga","Lihlala lilelo kanye","Liyawa kuba bechitha imali kwiivenkile"]}},"6":{"title":"Ukufunda iTshathi leXabiso","desc":"Amakhandlela, imigca, nokuba athetha ntoni","content":"Itshathi lexabiso lifana nevidiyo emfutshane yezona zinto ziphambili ezenzekileyo kwimbali yesabelo. Olona hlobo ludumileyo litshathi lamakhandlela. Ikhandlela ngalinye likubonisa izinto ezi-4 zosuku olunye:\\n\\n🟢 Ikhandlela eliluhlaza = ixabiso LINYUKILE ngaloo mini (livule lisezantsi, lavala liphezulu)\\n🔴 Ikhandlela elibomvu = ixabiso LEHLILE (livule liphezulu, lavala lisezantsi)\\n📏 Imigca emincinci engentla nengezantsi = elona xabiso liphezulu nelona lisezantsi losuku\\n\\nUkuba ubona amakhandlela amaninzi aluhlaza elandelelana, olo lutyekelo olunamandla olunyukayo. Amaninzi abomvu athetha utyekelo olwehlayo. Ukufunda ukuwafunda amatshathi kufana nokufunda ibhodi yamanqaku emdlalweni! 🎮","quiz":{"q":"Ubona amakhandlela abomvu ama-5 elandelelana kwitshathi. Oku kukuxelela ntoni?","options":["Isabelo besinyuka iintsuku ezi-5","Isabelo besisehla iintsuku ezi-5","Ixabiso lesabelo alitshintshanga"]}},"7":{"title":"Umthamo Nokuba Ukuxelela Ntoni","desc":"Zingaphi izabelo ezirhwetshwayo","content":"Umthamo = zingaphi izabelo ezithengwe zaza zathengiswa ngosuku. Cinga ngawo njengokubukelwa kwevidiyo ye-TikTok.\\n\\n🔊 Umthamo OPHEZULU = abantu abaninzi bayarhweba. Ukuba ixabiso lishukuma kunye nomthamo ophezulu, lowo ngumqondiso onamandla nothembeke ngakumbi, njengevidiyo ehamba ngenene, ingekho iibhothi.\\n\\n🔇 Umthamo OSEZANTSI = ngabantu abambalwa kuphela abarhwebayo. Amaxabiso anokushukuma ngendlela engaqhelekanga xa umthamo usezantsi, njengevidiyo ebukelwe kathathu kuphela eyabelwana ngempazamo.\\n\\nSoloko ujonga umthamo xa ubona ushukumo olukhulu lwexabiso. Lukuxelela ukuba olo shukumo lolwenene okanye yingxolo nje!","quiz":{"q":"Isabelo sika-{telco} sitsibe nge-5% namhlanje, kodwa umthamo usezantsi kakhulu. Kufuneka ucinge ntoni?","options":["Ngokuqinisekileyo leli lelona thuba likhulu, thenga ngoku!","Umthamo osezantsi uhlala uthetha ukuba ixabiso liza kuqhubeka linyuka","Olo shukumo lusenokungathembeki, umthamo osezantsi lwenza lukrokrise"]}},"8":{"title":"Inkxaso Nomqobo","desc":"Amanqanaba amaxabiso abalulekileyo","content":"Yenza umfanekiso wokuba ixabiso lesabelo yibhola edlobayo:\\n\\n🧱 INKXASO = umgangatho ibhola edlobela kuwo. Ixabiso lihlala lisehla kodwa qho xa lifika kweli nqanaba, litsiba libuyele phezulu. Abathengi abaninzi bavela apha.\\n\\n🪟 UMQOBO = usilingi ibhola ebetha kuyo. Qho xa ixabiso linyukela kweli nqanaba, lityhalelwa emva ezantsi. Abathengisi abaninzi bathatha imali yabo apha.\\n\\nAbarhwebi basebenzisa la manqanaba njengemephu yomdlalo: thenga kufuphi nomgangatho, thengisa kufuphi nosilingi. Xa ixabiso ekugqibeleni lityhala ludlule kumqobo, lidla ngokunyuka ngesantya. Xa liqhawula inkxaso, zilungiselele ukuwa! 💥\\n\\nSinye isilumkiso esinyanisekileyo: la manqanaba azotywa ngabantu abajonge amatshathi, ayingomithetho ekufuneka imarike iyithobele. Isabelo sinokudlula sitshabalalise 'inkxaso' siqhubeke sihamba. 📉","quiz":{"q":"Isabelo sidlobe kwi-{c}50 izihlandlo ezithathu ngaphandle kokuhla ngaphantsi kwayo. Ibizwa ntoni i-{c}50?","options":["Inqanaba lenkxaso","Inqanaba lomqobo","Ixabiso losilingi"]}},"9":{"title":"Ukusasaza uTyalo-mali","desc":"Musa ukubeka onke amaqanda kubhasikithi omnye","content":"Khawucinge ngokuchitha YONKE i-data yakho kwi-app enye yokubukela. Emva koko loo app iyaphuma. Usale ungenanto. 😩\\n\\nKodwa ukuba usasaza i-data yakho kuWhatsApp, kuYouTube, NAKWI-app yakho yokubukela, enye ephumayo ayonakalisi usuku lwakho lonke.\\n\\nKuyafana nasekutyaleni imali! Ukuba ufaka YONKE imali yakho kwisabelo esinye size siwe, ulahlekelwa yiyo yonke into. Kodwa ukuba uyisasaza ku-{telco} (unxibelelwano), ku-{retail} (iivenkile), ku-{tech} (itekhnoloji), nakwi-ETF, ukuwa kwesinye akuyitshabalalisi yonke iphothifoliyo yakho. Eli qhinga lokusasaza libizwa ngokuba KUKUSASAZA UTYALO-MALI. 💼","quiz":{"q":"Une-{c}500 yokutyala. Yeyiphi indlela ekhuselekileyo ngakumbi?","options":["Faka yonke i-{c}500 kwinkampani enye oyithandayo","Yigcine iyimali ephathekayo, ukutyala imali kunomngcipheko kakhulu","Yahlula i-{c}500 kwiinkampani ezi-5 ezahlukeneyo kumashishini ahlukeneyo"]}},"10":{"title":"Umngcipheko Nomvuzo","desc":"Kutheni inzuzo enkulu = umngcipheko omkhulu","content":"Wakhe wathenga ibhokisi ongazi ukuba kukho ntoni ngaphakathi? Usenokufumana into emangalisayo, okanye inkunkuma nje. Lowo ngumngcipheko ophezulu / umvuzo ophezulu.\\n\\nUkutyala imali kusebenza ngendlela efanayo:\\n\\n✅ UMNGCIPHEKO OSEZANTSI, UMVUZO OSEZANTSI: Njengo-{retail}: inkampani enkulu, esekwe kakuhle. Imali yakho idla ngokukhula kancinci kodwa ngokuzinzileyo. Qaphela 'osezantsi', kungekhona 'ongekhoyo'. Iinkampani ezinkulu nazo ziyawa.\\n\\n🎲 UMNGCIPHEKO OPHEZULU, UMVUZO OPHEZULU: Njengenkampani entsha encinci yemigodi. Inokuphindwa kalishumi, okanye inyamalale. Njengaloo bhokisi ungayaziyo.\\n\\nPhambi kokuba utyale imali kuyo nayiphi na into, soloko uzibuza: 'Yeyiphi eyona nto imbi inokwenzeka?' Ukuba awukwazi ukuphila ngaphandle kwaloo mali, sukuwuthatha loo mngcipheko!","quiz":{"q":"I-crypto entsha encinci engaziwa mntu ithembisa imbuyekezo eyi-500%. Yintoni inyaniso enyanisekileyo?","options":["Ngokuqinisekileyo iyinyani, imbuyekezo ephezulu isoloko ithetha utyalo-mali olungcono","Okukhona imbuyekezo ethenjisiweyo iphakama, kokukhona umngcipheko wokulahlekelwa yiyo yonke into usiba mkhulu","I-crypto isoloko ibetha izabelo ze-{ex}"]}},"11":{"title":"Ixesha Elide Nexesha Elifutshane","desc":"Ingqondo yokutyala imali nengqondo yokurhweba","content":"🏃 UKURHWEBA KWIXESHA ELIFUTSHANE: Ukuthenga nokuthengisa phakathi kweentsuku okanye iiveki ukubamba ushukumo olukhawulezayo lwexabiso. Uxinzelelo oluphezulu, kufuna ixesha elininzi ujonge iscreen. Kufana nokuzama ukuqikelela ukuba ngubani oza kuphumelela kumdlalo ngamnye kwitumente.\\n\\n🧘 UKUTYALA IMALI KWIXESHA ELIDE: Ukuthenga izabelo uze uzibambe iminyaka. Uyanyamezela xa zisehla uze uyeke imali yakho ikhule. Kufana nokubheja ukuba liliphi iqela eliza kuphumelela lonke usizini. Akothuki emva komdlalo omnye ombi.\\n\\nUphando ngeeakhawunti zokwenene zeebhrokha luhlala lufumana into efanayo: okukhona abantu berhweba rhoqo, kokukhona besilela ngakumbi xa sele kubalwe iindleko.\\n\\nKwaye ixesha lelona thuba elingenakuthengwa kamva. Unyaka ngamnye imali ehlala ityaliwe ngomnye unyaka wokuba inzala edibeneyo isebenze. ⏳","quiz":{"q":"Kutheni ukuqala ukutyala imali kwangethuba kubaluleke kangaka?","options":["Likhona ixesha elingakumbi lokuba inzala edibeneyo isebenze kwimali oyifakileyo","Abantu abaqala kwangethuba bakwazi ngcono ukukhetha izabelo","Imirhumo isezantsi kubantu abaqala kwangethuba"]}},"12":{"title":"{dcaTitle}","desc":"Tyala isixa esifanayo rhoqo","content":"Nali iqhinga elilula kangangokuba alivakali njengeqhinga, kwaye licima owona mbuzo unzima ekutyaleni imali:\\n\\nTyala isixa ESIFANAYO nyanga nganye, nokuba amaxabiso enyukile okanye ehlile. Njengokubeka bucala i-{c}100 kwimali yosuku lwakho lokuzalwa okanye kwimali oyinikwayo qho ngenyanga.\\n\\n📉 Xa amaxabiso ESEZANTSI → i-{c}100 yakho ithenga izabelo EZININZI\\n📈 Xa amaxabiso EPHEZULU → i-{c}100 yakho ithenga izabelo EZIMBALWA\\n\\nEkuhambeni kwexesha, ixabiso lakho eliphakathi kwisabelo ngasinye liyathamba, uzithengela 'ekwehleni' ngokuzenzekelayo ungazami nokuzama! Oku kubizwa ngokuba yi-{dcaTitle} ({dcaAbbrev}). Kususa iimvakalelo ekutyaleni imali kuba akusoze kufuneke ugqibe ukuba 'ngaba NGOKU lelona xesha lifanelekileyo?' Uyazibophelela nje uhambe! 💪\\n\\nIlizwi elithe ngqo: oku akusoze kuhlale kubetha ukufaka imali yonke ngaxeshanye. Into oyenzayo kukwenza isicwangciso onokuthi unamathele kuso ngokwenene.","quiz":{"q":"Utyala i-{c}200 nyanga nganye kungakhathaliseki ixabiso. Kwenye inyanga isabelo sitshiphu, kwinyanga elandelayo siyabiza. Yintoni ingenelo?","options":["Uhlala uthenga ngelona xabiso lisezantsi","Wenza imali kuphela xa amaxabiso enyuka","Ulinganisa iindleko zakho ekuhambeni kwexesha uze ususe iimvakalelo ekutyaleni imali"]}},"13":{"title":"Iintsana zeMali 💸","desc":"Ukuhlawulwa ngenxa nje yokubamba izabelo","content":"Khawufane ucinge ukuba unomatshini othengisa izidlo. Veki nganye, abantu bathenga izidlo KUMATSHINI WAKHO, wena uqokelele imali, ngenxa nje yokuba ungumnini wawo. Bekungekho nto yongezelelweyo ekufuneke uyenzile!\\n\\nZiyiloo nto ke iidividendi. Sizibiza ngokuba ziiNtsana zeMali 🍼 kuba imali yakho ngokwenene izala iintsana: iintlawulo ezincinci zemali ezifika kwiakhawunti yakho ngenxa nje yokuba unezabelo.\\n\\nIinkampani ezinkulu ezifana no-{divPayers} zihlawula iiNtsana zeMali rhoqo. Okukhona unezabelo ezininzi, kokukhona iintsana zakho zisiba zininzi!\\n\\n⚠️ AZIQINISEKISWANGA. Inkampani igqiba ngalo lonke ixesha ukuba iyahlawula na, kwaye inokuyinciphisa idividendi okanye iyiyeke ngokupheleleyo xa ishishini linzima. Intlawulo enkulu kulo nyaka ayisosithembiso senye kunyaka olandelayo.\\n\\nKwaye ukuba ezo ntsana uyaziphinda uzityale ukuze uthenge izabelo EZININZI... umqulu wakho olandelayo mkhulu ngakumbi. Sisijikelezo esihle 🔁","quiz":{"q":"U-{bank} ukuhlawula i-{c}5 kwisabelo ngasinye onaso, ngenxa nje yokubamba izabelo. Ibizwa ntoni le ntlawulo?","options":["Yidividendi (iNtsana yeMali)","Ngumrhumo wokurhweba","Yibhonasi yokuba ngumthengi"]}},"14":{"title":"Inzala Edibeneyo","desc":"Indlela imali yakho ekhula ngayo ngokwayo","content":"Nayi eyona mfihlelo yemali inamandla oza kuze uyifunde. Ulungile? 👀\\n\\nUtyala i-{c}1,000 nge-10% ngonyaka:\\n• Unyaka 1: {c}1,000 → {c}1,100 (ufumene {c}100)\\n• Unyaka 2: {c}1,100 → {c}1,210 (ufumene {c}110, ngaphezu konyaka 1!)\\n• Unyaka 3: {c}1,210 → {c}1,331 (ufumene {c}121)\\n\\nNgoku ufumana inzala KWINZALA yakho. Ibhola yekhephu ikhula minyaka le ungongezanga nto. Emva kweminyaka engama-30 nge-10%? Loo {c}1,000 iba yi-{c}17,449! 🤯\\n\\nUza kubona oku kubizwa ngokuba 'ngummangaliso wesibhozo wehlabathi' kubalelwa kuEinstein. Abukho ubungqina bokwenene bokuba wakha wakutsho, kodwa yimathematika ebalulekileyo, kwaye imathematika iyinyani. Qala kwangethuba, ixesha likwenzela umsebenzi onzima.","quiz":{"q":"Utyala i-{c}500 nge-10% ngonyaka ungaze uyichukumise. KuNyaka 2, ufumana inzala phezu kwantoni?","options":["Kuphela kwi-{c}500 yakho yantlandlolo","Kwi-{c}500 yakho KUNYE nenzala oyifumene kuNyaka 1","Kuphela kwinzala, kungekhona kwimali yakho yantlandlolo"]}},"15":{"title":"Inzala Edibeneyo Nezabelo","desc":"Ukuphinda utyale iiNtsana zeMali ukuze ukhule","content":"Uyazikhumbula iiNtsana zeMali (iidividendi)? Nantsi indawo apho kuba mnandi khona 🤯\\n\\nOkuqhelekileyo: Ufumana i-{c}50 kwiiNtsana zeMali → uyichithe kwizidlo → kugqityiwe.\\n\\nInyathelo elikrelekrele: Ufumana i-{c}50 kwiiNtsana zeMali → uthenge izabelo EZININZI → ngokulandelayo ufumane iiNtsana zeMali EZININZI → uthenge izabelo ezininzi ngakumbi → ibhola yekhephu iyahamba 🔝\\n\\nOku kukudibanisa kwenzala okusetyenziswe kwizabelo. Bala amanani: faka isixa esifanayo nyanga nganye iminyaka engama-30 ngembuyekezo ephakathi eyi-10%, uze uphelele kwiZIHLANDLO EZINTANDATHU zoko ukufakileyo ngokwenene. Malunga nezahlulo ezihlanu kwezithandathu zaloo mfumba lukhulo: imali ongazange uyisebenzele, uyonge okanye uyifake.\\n\\nKumaxesha amade, iidividendi eziphinde zatyalwa zenze inxalenye enkulu yembuyekezo iyonke yabatyali-mali. Yiyo kanye loo nto abahlawuli beedividendi 'abadikayo' bephela bengadiki konke konke 💰","quiz":{"q":"Endaweni yokuchitha i-{c}80 yakho yeedividendi, uzisebenzisa ukuthenga izabelo ezingakumbi. Kwenzeka ntoni emva koko?","options":["Ufumana iidividendi ezimbalwa ngokulandelayo kuba uzichithile","Iidividendi ziyayeka ukuba uphinda uzityale","Ngoku unezabelo ezininzi ngoko ke ufumana iidividendi EZININZI ngakumbi ngokulandelayo"]}},"16":{"title":"UMthetho we-72","desc":"Indlela ekhawulezayo yokuqikelela ixesha lokuphinda kabini","content":"Nali ikhowudi yobuqhophololo yengqondo yakho 🧠\\n\\nUfuna ukwazi ukuba kuthatha ixesha elingakanani ukuba imali yakho IPHINDE KABINI? Yahlula nje i-72 ngembuyekezo yakho yonyaka:\\n\\n• 72 ÷ 12% yembuyekezo = iminyaka emi-6 ukuphinda kabini\\n• 72 ÷ 8% yembuyekezo = iminyaka eli-9 ukuphinda kabini\\n• 72 ÷ 6% yembuyekezo = iminyaka eli-12 ukuphinda kabini\\n\\nNgoko ke ukuba ufumana i-12% ezinzileyo ngonyaka kwi-{c}2,000, kwiminyaka emi-6 uba ne-{c}4,000. Linda eminye iminyaka emi-6 uze ube ne-{c}8,000. Kweminye emi-6 uba ne-{c}16,000! 🤯\\n\\nLuqikelelo, ayingomthetho, kwaye imbuyekezo yokwenene ayisoze ibe linani elizinzileyo minyaka le. Kodwa isondele ngokwaneleyo ukuba uyibale entloko, yiyo yonke injongo leyo.\\n\\nYiyo le nto ukuqala kwiminyaka eli-13 okanye eli-14 KUKHULU KAKHULU. Unemijikelezo emininzi yokuphinda kabini ephambi kwakho kunabo bonke abanye abantu!","quiz":{"q":"Ufumana i-8% ngonyaka kutyalo-mali lwakho. Usebenzisa uMthetho we-72, mingaphi iminyaka yokuba imali yakho iphinde kabini?","options":["Iminyaka eli-9","Iminyaka esi-8","Iminyaka engama-72"]}},"17":{"title":"Imiyalelo yeMarike Neyomda","desc":"Iindlela ezimbini zokuthenga izabelo","content":"Zimbini iindlela eziphambili zokuthenga isabelo:\\n\\n⚡ UMYALELO WEMARIKE: 'Thenga ngoku nokuba ixabiso lingakanani.' Kufana nokufaka enqwelweni uze uhlawule ngoko nangoko kwi-{shop}. Uyifumana kwangoko, kodwa ixabiso olihlawulayo ngokwenene yiloo mali imarike ekunika yona, enokwahluka kwinani obusandul' ukulibona kwiscreen.\\n\\n🎯 UMYALELO WOMDA: 'Thenga kuphela ukuba ixabiso lehla lifika kwi-{c}X.' Kufana nokufaka into kuluhlu lwakho lweminqweno kwi-{shop} uze ulinde ithengiso. Wena ulawula ixabiso, kodwa intengiselwano isenokungenzeki tu.\\n\\nImiyalelo yomda ikunika ulawulo lwexabiso. Imiyalelo yemarike ikunika isiqinisekiso sokuba iyaphumelela. Awunakuba nazo zombini! 💸","quiz":{"q":"Ufuna ukuthenga izabelo ze-{tech} kodwa kuphela ukuba zehla zisuka kwi-{c}200 zisiya kwi-{c}180. Usebenzisa luphi uhlobo lomyalelo?","options":["Umyalelo wemarike, thenga ngoku kwi-{c}200","Umyalelo womda, misela usukelo kwi-{c}180 uze ulinde","Awunakumisela ixabiso elithile lokuthenga"]}},"18":{"title":"Imirhumo Neendleko zokuRhweba","desc":"Ukuqonda imirhumo yokurhweba","content":"Uninzi lweentengiselwano lukubiza imali encinci: ibhrokha ithatha isiqwenga esincinci. Le mirhumo ibizwa ngokuba yimirhumo yokurhweba okanye yimirhumo yebhrokha.\\n\\n⚠️ Ezinye iibhrokha zibhengeza 'ikhomishini engekhoyo'. Zisafuna ukwenza imali ngandlela ithile, ngoko ke ziyenza kwenye indawo, ngokuqhelekileyo kumsantsa omncinci phakathi kwexabiso lokuthenga nexabiso lokuthengisa, ekuguqulweni kwemali yamanye amazwe, okanye kwinzala yemali elele kwiakhawunti yakho. Isimahla sinqabile ukuba sibe sisimahla ngenene.\\n\\nKwi-NoobTrader imirhumo elinganiselweyo yile:\\n• Izabelo ze-{ex}: {exFee} kwintengiselwano nganye\\n• Izabelo zehlabathi: 0.50%\\n• Ii-ETF: 0.30%\\n• I-crypto: 0.60%\\n• I-forex: 0.05%\\n• Izinto ezingundoqo: 0.40%\\n\\nUmzekelo: Uthenga izabelo ze-{retail} ze-{c}1,000 kwi-{exFee}. Umrhumo yi-{c}{feeAmt}, ngoko ke uchitha i-{c}{feeTotal} ngokwenene.\\n\\nImirhumo emincinci idibana IKHAWULEZE ukuba urhweba rhoqo. Umntu owenza iintengiselwano ezingama-20 ngenyanga uhlawula loo mrhumo izihlandlo ezingama-20, aze awuhlawule kwakhona xa ephuma. Sesinye sezizathu zokuba abatyali-mali bexesha elide berhweba kancinci: iintengiselwano ezimbalwa, imirhumo emincinci 🧮","quiz":{"q":"Uthenga izabelo ze-{ex} ze-{c}1,000 ngomrhumo we-{exFee}. Ungakanani umrhumo?"}},"19":{"title":"Imiyalelo yokuMisa iLahleko","desc":"Zikhusele kwiilahleko ezinkulu","content":"Isimisi-lahleko sifana nokubeka umda wokuba ufuna ukulahlekelwa kangakanani: ngumnatha wokhuseleko owubeka kwangaphambili.\\n\\nUmzekelo: Uthenga izabelo ze-{telco} nge-{c}100 ngasinye. Ugqiba ukuba AWUFUNI ukulahlekelwa ngaphezu kwe-15%. Ngoko ke umisela isimisi-lahleko kwi-{c}85.\\n\\nUkuba u-{telco} wehla afike kwi-{c}85 → umyalelo wokuthengisa uyaziqhusheka ngokuzenzekelayo. Akufuneki ube ubukele, kwaye akufuneki wenze isigqibo ngelixa ungcangcazela.\\n\\n⚠️ Into enkulu: isimisi-lahleko siqhusheka UKUTHENGISA, asiliqinisekisi IXABISO. Ukuba kufika iindaba ezimbi ebusuku size isabelo sivule kwi-{c}70 singazange sirhwetshwe kwi-{c}85, umyalelo wakho uzaliseka nangayiphi na imali imarike eza kuyihlawula ngokwenene. Loo nto inokuba ngaphantsi kakhulu kwenqanaba olibekileyo.\\n\\nUngenaso konke konke isimisi-lahleko, usenokubambelela ulindele ukuba sichache... uze usibukele sisehla siya kwi-{c}20. 😬\\n\\nIcebo lengcali: Soloko ugqiba ngeyona lahleko inkulu unokuyithwala PHAMBI kokuba uthenge. Musa ukuvumela imvakalelo yenze eso sigqibo xa ixabiso sele lisiwa! 🧘","quiz":{"q":"Uthenga izabelo nge-{c}200 uze umisele isimisi-lahleko kwi-{c}170. Kwenzeka ntoni ukuba ixabiso lehla lifika kwi-{c}170?","options":["Umyalelo wokuthengisa uqhusheka ngokuzenzekelayo ukunciphisa ilahleko yakho","Uthenga izabelo ezingakumbi ngokuzenzekelayo","Akukho nto, isimisi-lahleko sibalulekile kwinzuzo kuphela"]}},"20":{"title":"Xa Kufuneka Uthenge Uze Uthengise","desc":"Ixesha, umonde, nengqeqesho","content":"Yeyiphi eyona mpazamo inkulu yenziwa ngabatyali-mali abatsha? Ukuthenga xa wonke umntu evutha ngumdla, uze uthengise xa wonke umntu engcangcazela. Yeyona nto ichaseneyo ncam noko kusebenzayo. 🤦\\n\\n📱 Xa iqela lakho lencoko ligcwele 'THENGA ESI SABELO NGOKU!!!!' → loo mdla sele ubandakanyiwe exabisweni. Ushiyekile.\\n\\n😱 Xa wonke umntu ethengisa engcangcazela → ngamanye amaxesha elo lithuba lokuthenga ngexabiso eliphantsi. Ngamanye amaxesha ixabiso liyaqhubeka lisehla omnye unyaka. Akakho umntu okhalisa intsimbi xa sele kusezantsi.\\n\\nYintoni imfihlelo? Yiba nesicwangciso PHAMBI kokuba utyale imali:\\n• Kutheni ndithenga le nto? (uphando, kungekhona umdla nje)\\n• Ndiza kuthengisa ngaliphi ixabiso ukuba LINYUKA? (thabatha inzuzo)\\n• Ndiza kuthengisa ngaliphi ixabiso ukuba LIYEHLA? (isimisi-lahleko)\\n\\nNamathela kwisicwangciso sakho. Musa ukuvumela iimvakalelo zakho zithathe indawo yeqhinga lakho! 💪","quiz":{"q":"Lonke iqela lakho lencoko lidumisa isabelo esele sinyuke nge-80% kule nyanga. Lithini inyathelo elikrelekrele?","options":["Thenga ngoko nangoko, iqela lihlala lichanile","Thengisa yonke enye into uze ufake yonke imali apha","Qala ngophando lwakho; umdla ngokuqhelekileyo uthetha ukuba ushukumo sele luphelile"]}},"21":{"title":"Yintoni iXabiso leMarike?","desc":"Indlela yokulinganisa ubukhulu benkampani","content":"Ixabiso lemarike likuxelela ubukhulu benkampani ngokwenene, libalwa ngale mali: {cPlural}.\\n\\n📐 Ifomyula: Ixabiso leSabelo × Inani Lilonke Lezabelo = Ixabiso leMarike\\n\\nUmzekelo: Ukuba u-{retail} unezabelo eziyibhiliyoni enye size isabelo ngasinye sibize i-{c}50, ixabiso lemarike yi-{c}50 IYIBHILIYONI. Lelo lixabiso elibekwe kuyo yonke inkampani.\\n\\n🔵 Ixabiso elikhulu: awona magama makhulu, asekwe kakhulu, njengo-{tech} no-{bank}. Umngcipheko osezantsi, ukukhula okucothayo ngokuqhelekileyo.\\n🟡 Ixabiso eliphakathi: iinkampani eziphakathi ngobukhulu. Umngcipheko olinganiselweyo.\\n🔴 Ixabiso elincinci: iinkampani ezincinci kakhulu. Zinokukhula ngokukhawuleza OKANYE ziwe kabuhlungu.\\n\\n⚠️ Le mida ayifani kuwo onke amazwe. E-US, 'ixabiso elikhulu' ngokuqhelekileyo lithetha into engaphezu kwe-$10 yebhiliyoni, kodwa imarike nganye imisela eyayo imida, ngoko ke ixabiso elikhulu e{name} alilingani nexabiso elikhulu e-US. Funda inani lokwenene, kungekhona nje ilebhile 🧐","quiz":{"q":"Inkampani inezabelo ezizizigidi ezili-10 size isabelo ngasinye sibize i-{c}50. Lingakanani ixabiso lemarike?","options":["{c}50 wezigidi","{c}500 wezigidi","{c}5 yebhiliyoni"]}},"22":{"title":"Umlinganiso we-P/E Uchaziwe","desc":"Ngaba isabelo siyabiza okanye sitshiphu?","content":"Umlinganiso we-P/E (iXabiso kwiNgeniso) ukuxelela ukuba uhlawula malini ukuze ufumane {cName} enye yenzuzo yenkampani.\\n\\n📐 Ifomyula: Ixabiso leSabelo ÷ Ingeniso kwiSabelo ngaSinye = Umlinganiso we-P/E\\n\\nCinga ngawo njengexabiso lecwecwe ngalinye lepizza 🍕\\n\\nUkuba ipizza A ibiza i-{c}80 ngamacwecwe asi-8 = {c}10/icwecwe\\nUkuba ipizza B ibiza i-{c}100 ngamacwecwe ama-5 = {c}20/icwecwe\\n\\nIpizza A itshiphu kwicwecwe ngalinye. Yingcinga efanayo kwizabelo:\\n• I-P/E esezantsi (ngaphantsi kwe-10) = mhlawumbi lithuba elihle, OKANYE imarike ilindele ukuba inzuzo yayo IWE. I-P/E esezantsi ngumbuzo, ayimpendulo.\\n• I-P/E ephezulu (ngaphezu kwe-25) = imarike ilindele ukukhula okukhulu kwixesha elizayo. Emva koko inkampani kufuneka ikwenze ngokwenene.\\n\\nSoloko uthelekisa i-P/E NEZINYE iinkampani kwishishini elinye. Musa ukuthelekisa i-P/E yebhanki neyenkampani yetekhnoloji!","quiz":{"q":"Inkampani A ine-P/E eyi-8. Inkampani B (kwishishini elinye) ine-P/E engama-30. Oku kubonisa ntoni?","options":["Inkampani A itshiphu kwiyunithi nganye yenzuzo, kodwa fumanisa ukuba KUTHENI phambi kokuba uthenge","Inkampani B ihlala ilutyalo-mali olungcono","Umlinganiso we-P/E awuncedi kwizigqibo zotyalo-mali"]}},"23":{"title":"Ukufunda iZiphumo zeNkampani","desc":"Ingeniso, inzuzo, nokubalulekileyo","content":"Emva kweenyanga ezimbalwa, iinkampani zipapasha 'ikhadi lazo lengxelo' (kwikota nganye kwezinye iimarike, kabini ngonyaka kwezinye), kwaye lishukumisa amaxabiso ezabelo KAKHULU. Nantsi into omawuyijonge:\\n\\n📊 INGENISO: Imali iyonke engenayo ivela kwiintengiso. Njengemali eyingenileyo kwivenkile encinci iyonke.\\n💰 INZUZO ESELEYO: Okuseleyo EMVA kokuhlawula zonke iindleko. Yiyo imali eshiyekayo ekupheleni kosuku.\\n📈 I-EPS (Ingeniso kwiSabelo ngaSinye): Inzuzo yahlulwe ngenani lezabelo. Ingakanani imali efunyenwe sisabelo ngasinye.\\n\\nImiqondiso emihle: Ingeniso INYUKA + Inzuzo INYUKA + I-EPS iyakhula = 🟢 ixabiso lidla ngokunyuka\\nImiqondiso emibi: Ingeniso IYEHLA + Inzuzo iyehla = 🔴 ixabiso lidla ngokwehla\\n\\nNantsi into: eyona nto ishukumisa ixabiso sisiphumo xa sithelekiswa noko imarike YAYIKULINDELE. Amanani amahle afike ngaphantsi koko bekulindelwe asenokusithumela isabelo ezantsi.\\n\\nInkampani inokuba nengeniso enkulu kodwa ingabi nanzuzo (iindleko eziphezulu). Soloko ujonga ZOMBINI!","quiz":{"q":"U-{bank} unika ingxelo yengeniso enyuke nge-15% kodwa inzuzo yehle nge-20% ngenxa yeendleko eziphezulu. Ngaba lo ngumqondiso omhle okanye omubi?","options":["Mhle: ingeniso inyukile, kuphela koko kubalulekileyo","Mhle kakhulu: nokuphi ukukhula kulungile","Uxubene okanye mubi: benza iintengiso ezingakumbi kodwa begcina imali encinci"]}},"24":{"title":"Amacandelo Namashishini","desc":"Iintlobo ezahlukeneyo zeenkampani","content":"Imarike yezabelo yahlulwe yangamacandelo, njengamasebe ahlukeneyo esikolweni.\\n\\n{sectorList}\\n\\nAmacandelo ahlukeneyo ayanyuka aze ehle ngamaxesha ahlukeneyo, yiyo yonke injongo yokusasaza phakathi kwawo! Ukuba iibhanki ziyawa, mhlawumbi itekhnoloji iyaphakama. Iphothifoliyo yakho ihlala ilinganisiwe. 🎯","quiz":{"q":"Amazinga enzala e{name} anyuka kakhulu. Leliphi icandelo elidla ngokuzuza ngakumbi?","options":["Iivenkile: abantu baza kuchitha ngakumbi","Iibhanki: iibhanki zidla ngokufumana umsantsa obanzi phakathi koko zikubiza kwababolekayo noko zikuhlawula kwabongayo","Itekhnoloji: ii-app ziba tshiphu"]}},"25":{"title":"Yintoni i-ETF?","desc":"Thenga ibhasikithi lonke ngaxeshanye","content":"Ngaphambili, ekuphela kwendlela yokwakha uluhlu lweengoma yayikukukhetha ingoma nganye. Emva koko kwafika iSpotify yakunika uluhlu lweengoma sele lwenziwe: ingqokelela ekhawulezayo, ungabulaleki. 🎵\\n\\nIi-ETF (iiNgxowa-mali ezirhwetshwa eQongeni) ziyiSpotify yotyalo-mali. Endaweni yokukhetha izabelo esinye ngasinye, uthenga i-ETF ENYE ephethe ibhasikithi lonke lazo.\\n\\nUninzi lwee-ETF lulandela ISALATHISI: uluhlu olupapashiweyo lweenkampani oludityaniswe ngokwencwadi yemithetho. {etfDesc} I-ETF ithenga nje oko kukuluhlu, ngamacandelo afanayo, ize izihlaziye xa uluhlu lutshintsha.\\n\\nNgoko ke i-ETF enye ye-{etf} ikunika isuntswana le-{etfBasket} (amagama afana no-{top5}) ngokuthenga kanye.\\n\\n⚠️ Isalathisi ASIKOKO 'iinkampani ezinkulu' ngokuzenzekelayo. Olunye uluhlu lulandelelanisa ngobukhulu, olunye ngokuba isabelo sirhwetshwa kangakanani, olunye lukhethwa yikomiti. Izalathisi ezibini kwiqonga elinye zinokuba neenkampani ezahluke ngokupheleleyo. Soloko ufunda ukuba olo luhlu luyintoni ngokwenene phambi kokuba ulithenge.\\n\\nNgokuqhelekileyo ii-ETF zitshiphu, zilula kwaye zisasazeke ngakumbi kunokuzikhethela izabelo ngokwakho. Abaphathi bengxowa-mali abaninzi abangoochwepheshe abakwazi ukuzibetha! 🤯","quiz":{"q":"Uthenga i-ETF enye ye-{etf}. Ngoku ungumnini wantoni?","options":["Isuntswana le-{etfBasket}, konke ngaxeshanye","Isabelo esinye kwinkampani enye enkulu","Kuphela eyona nkampani inkulu kwi-{ex}"]}},"26":{"title":"Ii-ETF ze-{ex}","desc":"Ii-ETF ezidumileyo omele uzazi","content":"Zininzi ii-ETF neengxowa-mali zesalathisi onokuzithenga e{name}. Nazi ezinye zezona zidumileyo:\\n\\n{etfList}\\n\\nOwona mkhethe mkhulu wee-ETF: IMIRHUMO. Iingxowa-mali ezininzi ezilawulwa ngabantu zibiza malunga ne-1% ukuya kwi-2% ngonyaka, ngamanye amaxesha ngaphezulu. Ii-ETF zesalathisi esibanzi zidla ngokubiza ngaphantsi kwe-0.2%. Kutyalo-mali lwe-{c}10,000 olugcinwe iminyaka engama-20, loo msantsa ungangaMAWAKA ({cPlural}) 💸\\n\\nJonga umrhumo phambi kokuba uthenge. Ngokuqhelekileyo ubhalwe ngokuthi 'TER' okanye 'expense ratio'. Akakho onokukuxelela ukuba i-ETF iza kubuyisa malini, kodwa umrhumo linani elinye ONOKULAZI kwangaphambili.","quiz":{"q":"Ufuna ukutyala imali ku-Apple, u-Alphabet no-Amazon kodwa awukwazi ukuthenga isabelo kwinye nganye. Yeyiphi eyona ndlela ilula?","options":["Yonga iminyaka de ukwazi ukuthenga nganye","Kufuneka uthenge isabelo senkampani nganye ngokwahlukeneyo","Thenga i-ETF elandela i-S&P 500, zontathu sele zikuyo"]}},"27":{"title":"Ii-ETF zeHlabathi Nezasekhaya","desc":"Ukutyala imali ekhaya nangaphesheya","content":"Ngaba kufuneka utyale imali kwiinkampani zase{name} kuphela? Impendulo emfutshane: Hayi! Nasi isizathu:\\n\\n🏠 II-ETF ZASEKHAYA: Zityala imali kwiinkampani zase{name}. Uyawazi la maphawu, athengiswa ngale mali: {cPlural}. Kodwa ukuba uqoqosho lwase{name} luyasokola, yonke iphothifoliyo yakho inokwehla.\\n\\n🌍 II-ETF ZEHLABATHI: Zityala imali kwiinkampani zamanye amazwe (i-US, iYurophu, i-Asia). {currencyHedge}\\n\\nNoko ke, imali yelizwe isika macala omabini: ukuba imali yakho yasekhaya IYOMELELA, ezo zinto zaphesheya zixabiseka ngaphantsi ekhaya. Yiloo ntengiselwano oyamkelayo ngokuba nezinto zaphesheya.\\n\\nUkubamba zombini ezasekhaya nezehlabathi kukusasaza kwimingcipheko emibini eyahlukeneyo ngaxeshanye: uqoqosho lwakho, nemali yakho. Ukulinganisa yinto yonke! ⚖️","quiz":{"q":"{fxQuizSetup}. Kwenzeka ntoni kwixabiso le-ETF yakho yehlabathi xa libalwa ngemali yakho ({cName})?","options":["{fxQuizLose}","{fxQuizGain}","Lihlala lilelo, imali yelizwe ayizichaphazeli ii-ETF"]}},"28":{"title":"Ukonga Nokutyala Imali","desc":"Kutheni imali yakho kufuneka isebenze","content":"Zombini zilungile. Kodwa zineenjongo ezahlukeneyo:\\n\\n🏦 UKONGA: Ufaka imali kwiakhawunti yasebhankini. Ikhuselekile, unokuyifikelela nangaliphi na ixesha. KODWA amazinga enzala ngokuqhelekileyo akwi-{savings}, ngokufuthi angaphantsi kwe-inflation. Imali yakho 'ikhuselekile' kodwa iphelelwa ngamandla okuthenga kancinci kancinci.\\n\\n📈 UKUTYALA IMALI: Ufaka imali kwizabelo, kwii-ETF okanye kwipropati. Umngcipheko ongakumbi, kwaye akukho siqinisekiso nakuwuphi na unyaka. Kweminye iminyaka ulahlekelwa nje yimali. Noko ke, kumaxesha amade, izabelo ngokwembali zibuyise ngaphezu kwemali ephathekayo. Imarike yase{name} ibe malunga ne-{mktReturn} ngonyaka ngokuphakathi kwixesha elidlulileyo, kwaye imilinganiselo yangaphambili yimbali, ayisosithembiso.\\n\\nUmthetho oqhelekileyo:\\n• Iinyanga ezi-3 ukuya kwezi-6 zeendleko zakho zibe kwimali eyongiweyo (ingxowa yakho yeemeko ezingxamisekileyo) 🚨\\n• Imali ongazukuyidinga iminyaka yile abantu bayityalayo 🚀\\n\\nMusa ukutyala imali onokuyidinga kwinyanga ezayo. Kuloko ukonga kukhoyo!","quiz":{"q":"Une-{c}5,000 kwimali eyongiweyo. Iindleko zakho zenyanga zi-{c}800. Kufuneka kuhlale malini kwimali eyongiweyo njengengxowa yeemeko ezingxamisekileyo?","options":["{c}2,400 ukuya kwi-{c}4,800 (iindleko zeenyanga ezi-3 ukuya kwezi-6), utyale okuseleyo","Yonke i-{c}5,000, ukonga kuhlala kukhuselekile ngakumbi","{c}0, tyala yonke into ukuze ukhule kakhulu"]}},"29":{"title":"I-Inflation Nemali Yakho","desc":"Kutheni imali iphelelwa lixabiso ekuhambeni kwexesha","content":"Buza umntu omdala ukuba yayibiza malini {food} ngexesha wayeselula njengawe. Yayimalunga ne-{c}{foodOld}. Ngoku yi-{c}{foodNew}+. Leyo yi-inflation: amaxabiso enyuka kancinci ekuhambeni kwexesha, oko kuthetha ukuba {cName} nganye ithenga OKUNCINCI kunangaphambili.\\n\\nI-inflation yase{name} ngokuqhelekileyo ibe malunga ne-{inflation} ngonyaka.\\n\\nNgoko ke ukuba imali yakho eyongiweyo ifumana i-4% ngonyaka kodwa i-inflation ingu-6%, ngokwenene ULAHLEKELWA malunga ne-2% yamandla okuthenga minyaka le, nangona ibhalansi yakho inyukile!\\n\\n💡 Utyalo-mali lwakho kufuneka lubethe i-inflation ukuze lukhulise ubutyebi bakho ngokwenene.\\n• Imali ephantsi komatrasi: iphelelwa lixabiso minyaka le 💀\\n• Ukonga ebhankini: ngokufuthi kuyasokola ukuhambelana nayo\\n• Izabelo ze-{ex} (umlinganiselo wexesha elide): {mktReturn} ngonyaka. Ngumlinganiselo wangaphambili, ayisosithembiso 🔥\\n\\nUkutyala imali akukokuba sisityebi kuphela. Kukungabi lihlwempu ngakumbi! 💸","quiz":{"q":"I-inflation ingu-6% kulo nyaka. Iakhawunti yakho yokonga ifumana i-4%. Kwenzeka ntoni kumandla akho okwenene okuthenga?","options":["Ayakhula nge-4%","Ahlala enjalo, inzala icima i-inflation","Ayancipha malunga nge-2%, ngokwenene uthenga okuncinci"]}},"30":{"title":"Iimvakalelo Nokutyala Imali","desc":"Musa ukuthengisa ungcangcazela okanye uthenge usoyika ukushiyeka","content":"Imarike yezabelo ngokusisiseko luvavanyo lokuzilawula kweemvakalelo. Uninzi lwabantu luyaluwa. 🎭\\n\\n😱 UKUTHENGISA NGOKUNGCANGCAZELA: Imarike yehla nge-20%, uyothuka, uthengise yonke into. Emva koko iyachacha. Ulahlekelwe ngaphandle kwesizathu.\\n\\n🤑 UKUTHENGA NGOKOYIKA UKUSHIYEKA: Wonke umntu kwi-social media udumisa ingqekeza ethile. Ubaleka ungene. Ixabiso liyawa ngoko nangoko. Usale uphethe ingxowa.\\n\\nAbona batyali-mali balungileyo baphatha ukuwa kwemarike njengokuthengisa okuthobekileyo kwa-{retail}. Bayaqhubeka bethenga, bezolile, endaweni yokungcangcazela. UWarren Buffett wakubeka watsho: 'Yoyika xa abanye bebawa, ube ubawa xa abanye besoyika.'\\n\\nYakha isicwangciso sakho. Namathela kuso. Wena wexesha elizayo uza kubulela ngokungathengisanga ngomsindo ngosuku olubomvu! 🙏","quiz":{"q":"Imarike yehla nge-15% kwiveki enye. Wonke umntu kwiqela lakho lencoko uyathengisa. Wenza ntoni ngokuqhelekileyo umtyali-mali okrelekrele wexesha elide?","options":["Uthengisa yonke into ngoko nangoko ukumisa iilahleko","Uhlala ezolile, aphinde ajonge isicwangciso sakhe, kwaye mhlawumbi athenge ngakumbi ngexabiso eliphantsi","Ujonga i-social media efuna amacebo okuba athenge ntoni endaweni yoko"]}},"31":{"title":"IBhosi Yokugqibela","desc":"Inzala Edibeneyo, ummangaliso wesi-8 wehlabathi","content":"'Ummangaliso wesibhozo wehlabathi: lowo uwuqondayo, uyawufumana; lowo ungawuqondiyo, uyawuhlawula.' Uza kuwubona loo mgca ubalelwa kuEinstein yonke indawo kwi-intanethi. Abukho ubungqina bokwenene bokuba wakutsho.\\n\\nNoko ke, imathematika ayiphikiseki. Nantsi eyona nto ibalulekileyo oza kuyifunda ngemali:\\n\\nUmntu oqala eneminyaka engama-20 aze atyale i-{c}500 ngenyanga nge-12% ngonyaka uphelela eneMALI ENGAKUMBI xa eneminyaka engama-65 kunomntu oqala eneminyaka engama-35 aze atyale i-{c}2,000 ngenyanga ngezinga elifanayo. Isixa senyanga siphindwe kane, kodwa usagqiba engasemva.\\n\\nIxesha. Yiyo. Yonke into.\\n\\nAyilobuqhophololo bamanani, yiyo yonke injongo yenzala edibeneyo: unyaka ngamnye owulindayo ubiza ngaphezu koko nawuphi na unyaka owongeza kamva unokukubuyisa. Elona xesha lilungileyo lokuqala belidlule kudala. Elilandelayo lelokwangoku.\\n\\nOlu vavanyo lolokugqibela. Luphumelele uze ube ngumntu onesatifikethi se-NoobTrader ngokusesikweni! 👑","bossVictory":"Inzala Edibeneyo ivuliwe. Uyingozi ngoku. 🔥","quiz":{"q":"I-{c}1,000 etyalwe nge-12% ngonyaka iminyaka eli-10 ikhula ifike malunga ne-{c}3,106. Kwenzeka ntoni ukuba UPHINDA KABINI ixesha libe yiminyaka engama-20?","options":["Iphindwa ngaphezu kwakathathu ifike malunga ne-{c}9,646","Iphindwa kabini malunga ne-{c}6,200","Imbuyekezo iyacotha okukhona ulinda ixesha elide"]}},"32":{"title":"Amaqonga e-Crypto Nezipaji","desc":"Apho i-crypto ihlala khona ngokwenene","content":"Okokuqala, inyaniso: amaqonga e-crypto okwenyani afuna ukuba ube neminyaka eyi-18+ phantse kuwo onke amazwe. Yiyo loo nto i-NoobTrader ikuvumela ukuba uqale uziqhelanise nayo yonke le nto ngemali yokuzilolonga. 🎮\\n\\nXa abantu abadala bethenga i-crypto, basebenzisa iindidi ezimbini zeendawo:\\n\\n🏦 AMAQONGA NEE-APP ZEEBHROKHA (zibamba egameni lakho): wenza iakhawunti, bona bakubambele i-crypto yakho. Kulula, kodwa uyabathemba. Ukuba bayagqekezwa okanye bayawa, i-crypto yakho inokunyamalala. Sekwenzekile kumanye amagama amakhulu kwi-crypto.\\n\\n🔑 IZIPAJI OZIBAMBELA WENA: yi-app apho WENA ubamba izitshixo eziyimfihlo. Akakho onokuyivala, kodwa akakho nonokukunceda. Lahlekelwa ngamagama akho embewu (amagama ayimfihlo ali-12 ukuya kwangama-24) uze i-crypto ihambe ngonaphakade. Akukho kusetwa kwakhona kwephasiwedi. Akukho nkxaso yabathengi. Ihambile.\\n\\nAbantu be-crypto bathi: 'Ukuba izitshixo asizizo zakho, iingqekeza azizizo zakho.' Ngoku uyayazi ukuba oko kuthetha ntoni.","quiz":{"q":"Kuthetha ntoni xa iqonga libamba i-crypto yakho 'egameni lakho'?","options":["I-crypto itshixiwe kwaye akakho onokuze ayichukumise","Wena ubamba izitshixo eziyimfihlo kwaye nguwe wedwa oyilawulayo","Iqonga libamba izitshixo, ngoko ke uyalithemba ngayo","Ifumana inzala ngokuzenzekelayo"]}},"33":{"title":"Indlela Ukuthenga i-Crypto Okusebenza Ngayo","desc":"Imisantsa, imirhumo, neemarike zeeyure ezingama-24","content":"Ukuthenga i-crypto kubonakala ngathi kukuthenga nantoni na kwi-intanethi, kodwa zintathu izinto ezahlukileyo:\\n\\n1️⃣ UMSANTSA: ixabiso lokuthenga lihlala liphakame kancinci kunexabiso lokuthengisa. Thenga i-crypto ye-{c}100 uze uyithengise ngoko nangoko, ufumana mhlawumbi i-{c}97. Loo msantsa yindlela amaqonga enza ngayo imali ngokuzolileyo.\\n\\n2️⃣ IMIRHUMO PHEZU KOKO: amaqonga amaninzi abiza nomrhumo kwintengiselwano nganye, ngokufuthi i-1 ukuya kwi-2% xa uthenga kancinci. Imirhumo kunye nomsantsa kuthetha ukuba ukuthenga okuncinci kuqala kusezantsi malunga ne-3 ukuya kwi-5% phambi kokuba ixabiso lishukume nokushukuma.\\n\\n3️⃣ AYIKHO INTSIMBI YOKUVALA: amaqonga ezabelo ayavala ebusuku nangeempelaveki. I-crypto irhwetshwa yonke imizuzu yosuku, yonke imihla yonyaka. Amaxabiso anokuwa ngelixa ulele. Yinxalenye yesizathu sokuba i-crypto iguquguquke ngakumbi kunezabelo.\\n\\nKwi-NoobTrader unokurhweba i-crypto ngemali yokuzilolonga uze ubukele la mandla esebenza ungalahlekelwa nayisenti. 📊","quiz":{"q":"Uthenga ingqekeza ye-{c}100 uze uyithengise emva kwemizuzwana emi-5. Kutheni ufumana okuncinci kune-{c}100?","options":["Umsantsa nemirhumo bathatha isiqwenga kwicala ngalinye","Amaxabiso e-crypto ahlala esiwa emva kokuba uthengile","Iqonga libiza irhafu","Unokuthengisa kuphela emva kweeyure ezingama-24"]}},"34":{"title":"Imirhumo ye-Gas Ichaziwe","desc":"Kutheni ukuthumela i-crypto kubiza imali","content":"Ukuthumela i-crypto akusimahla. Intengiselwano nganye ihlawula umrhumo wothungelwano, odla ngokubizwa ngokuba yi-GAS, kwiikhompyutha eziqhuba zize zikhusele uthungelwano.\\n\\nNantsi indawo emangalisa wonke umntu: i-gas ibekwa ixabiso ngokuxakeka kothungelwano, KUNGEKHONA ngobungakanani bemali oyithumelayo. Xa uthungelwano luxakekile, imirhumo iyadubula.\\n\\n🤯 Kwezinye iithungelwano, ngamaxesha oxakeko, ukuthumela i-crypto ye-{c}10 kunokubiza NGAPHEZU kwe-{c}10 kwi-gas. Ubuya kuhlawula ngaphezulu kuhambiso kunexabiso lomthwalo ngokwawo.\\n\\nIithungelwano ezitsha kunye neenkqubo 'zomaleko wesibini' zikhona ikakhulu ukwenza oku kube tshiphu, ngemirhumo yeesenti ezimbalwa. Nabani na ojongene ne-crypto ujonga umrhumo PHAMBI kokuba acofe uthumele.\\n\\nNenye into: ukuthunyelwa kwe-crypto akunakubuyiselwa umva. Idilesi engachananga kunye ne-gas ehlawulweyo kulingana nemali ehambe ngonaphakade. Akukho bhanki onokuyifowunela. ☎️❌","quiz":{"q":"Imirhumo ye-gas iphezulu namhlanje. Ufuna ukuthumela i-crypto ye-{c}15 kodwa i-gas ibiza i-{c}20. Yeyiphi into ekrelekrele omawuyibone?","options":["Yithumele, imirhumo iyabuya kamva","Thumela isiqingatha, ukuze umrhumo uhle isiqingatha","I-gas isebenza kuphela kutshintsho olukhulu, ngoko simahla ngaphantsi kwe-{c}50","Musa ukuyithumela, kuba umrhumo ubiza ngaphezu koko okuthunyelwayo kuxabisa khona"]}},"35":{"title":"Iingqekeza Zamahlaya Nokutsalwa Komata","desc":"Bona imigibe phambi kokuba ikubone","content":"Iingqekeza zamahlaya zii-crypto ezakhelwe kumahlaya nakumdla endaweni yokusebenza okwenene. Ezimbalwa zenza abathengi bokuqala baba zizityebi, yiyo kanye loo nto zikhoyo iiwaka zabakhuphelayo. Phantse zonke zehla zisiya kwiqanda. 📉\\n\\nOwona mgibe umbi kukuTSALWA KOMATA: abadali benza ingqekeza, bayidumise kakhulu, balinde ukuba abantu bangene ngobuninzi, baze bathengise imfumba yabo enkulu okanye bakhuphe yonke imali kwichibi lorhwebo. Ixabiso liyawa ngemizuzu. Bona bagcina imali. Wena ugcina iingqekeza ezingenaxabiso.\\n\\n🚩 IMIQONDISO EBOMVU omawuyibambe ngengqondo:\\n• Iqela elingaziwayo ongenakuliqinisekisa\\n• Imbuyekezo 'eqinisekisiweyo' (akukho nto iqinisekisiweyo kwiimarike)\\n• Abanempembelelo abahlawulwayo ukuba bayidumise\\n• Iqela elincinci liphethe uninzi lwezikhoyo\\n• Uxinzelelo lokuba 'uthenge ngaphambi kokuba kube semva kakhulu'\\n\\nUkuba eyona nto ingqekeza izikhankanya ngayo kukuba ABANYE abantu abayithengayo baza kwenza WENA ube sisityebi, oko akusiyondlela yokutyala imali. Ngumdlalo wezitulo zomculo, kwaye abadali ngabo abaphethe umculo. 🎵","quiz":{"q":"Ingqekeza entsha kwaphela inelinye iqela elingaziwayo, ithembisa 'ukuphindwa kali-100 okuqinisekisiweyo' kwaye abanempembelelo abahlawuliweyo bayityhala kakhulu. Ibizwa ntoni le ndlela?","options":["Lutyalo-mali oluzinzileyo lweenkampani ezinkulu","Yindlela eqhelekileyo yokutsalwa komata","Kukulinganisa iindleko ngedola","Yingqekeza ezinzileyo"]}},"36":{"title":"Ukumba, Ukurhweba, Nokubopha","desc":"Imidlalo emithathu eyahluke kakhulu","content":"Zintathu iindlela abantu abazama ukufumana imali ngazo kwi-crypto, kwaye AWUFANI umdlalo:\\n\\n⛏️ UKUMBA: iikhompyutha ezinamandla ziyakhuphisana ukuqhuba iintengiselwano zize zifumane iingqekeza ezintsha. Kuvakala kumnandi, kodwa ukumba i-Bitcoin namhlanje kushishino: iindawo zokugcina ezizele ngoomatshini abakhethekileyo kunye namatyala ombane amakhulu. Ifowuni yakho okanye ilaptop ayinakukhuphisana, kwaye ii-app ezithi 'mba i-Bitcoin kwifowuni yakho!' phantse zihlala zibubuqhetseba okanye ziipulazi zeentengiso ezikuhlawula phantse kungabikho nto.\\n\\n🥩 UKUBOPHA: kwezinye iithungelwano ubopha iingqekeza ukunceda ukukhusela uthungelwano uze ufumane imivuzo, ngathi yinzala. Kuyinyani, kodwa iingqekeza zakho zinokutshixwa ithuba, kwaye IXABISO lazo lisenokuwa ngelixa zitshixiwe.\\n\\n📊 UKURHWEBA: ukuthenga nokuthengisa ukuze uzuze kushukumo lwexabiso. Akukho zixhobo zifunekayo, kodwa ngumdlalo apho ingqeqesho ibaluleke khona kakhulu, nalapho uninzi lwabaqalayo lubethwa ziimvakalelo zabo.\\n\\nI-NoobTrader ikufundisa umdlalo wokurhweba ngaphandle komngcipheko. Le mibini iseleyo ifuna imali yokwenene ukuze uqale nokuqala.","quiz":{"q":"I-app ithi ifowuni yakho inokumba i-Bitcoin ngenzuzo ngelixa ulele. Yintoni eyona nyaniso inokwenzeka?","options":["Iifowuni zimba kancinci kodwa ngenzuzo ukuba zishiywe zitshaja","Yinyani kodwa isebenza kuphela kwiifowuni ezintsha","Phantse ngokuqinisekileyo bubuqhetseba okanye ihlawula phantse ingento, kuba iifowuni azinakukhuphisana nabambi bemizi-mveliso","Ukumba akukho mthethweni kwiifowuni"]}},"37":{"title":"Ukhuseleko lwe-Crypto Nobuqhetseba","desc":"Gcina okwakho kukokwakho","content":"Amandla amakhulu e-crypto akwangumngcipheko wayo: iintengiselwano azinakubuyiselwa umva kwaye akukho bhanki inokuyilungisa impazamo. Abaqhetsebi bayakuthanda oko. Nasi isixhobo sakho sokuzikhusela:\\n\\n🔐 AMAGAMA AKHO EMBEWU AYINGCWELE. Akakho umntu osemthethweni oza KUZE awacele. Hayi 'abasebenzi benkxaso', hayi 'ibhothi yokuqinisekisa', akakho. Nabani na ocela amagama akho embewu uyakubela, kuphelile apho.\\n\\n🎣 UKUDOBA: iiwebhusayithi nemiyalezo yobuxoki ebonakala kanye njengamaqonga okwenene. Unobumba omnye owahlukileyo kwidilesi yewebhu. Soloko uyibhala ngokwakho idilesi.\\n\\n🎁 UBUQHETSEBA BEZIPHO: 'Thumela ingqekeza enye, ufumane ezimbini!', ngokufuthi besebenzisa iakhawunti egqekeziweyo yomntu odumileyo. Akakho ophinda kabini imali yakho. Nakanye.\\n\\n💕 UBUQHETSEBA BOTHANDO NOBOMCEBISI 'WOTYALO-MALI': umntu ongaziwayo onobubele okuthethelela ngokuthe chu ukuba uye 'kwiqonga elikhethekileyo'. Iqonga lobuxoki. Ukukhupha imali akusebenzi.\\n\\nIndlela ephantsi kwabo bonke ubuqhetseba: ukungxamiseka kunye nemfihlo kunye nenzuzo eqinisekisiweyo. Xa ubona ezo zinto zintathu kunye, hamba uyeke. 🚶","quiz":{"q":"Umntu othi 'yinkxaso yeqonga' ukuthumelela umyalezo ecela amagama akho embewu ali-12 ukuze 'aqinisekise isipaji sakho'. Wenza ntoni?","options":["Ungaze wabelane ngawo, kuba inkxaso yokwenene ayiwaceli amagama embewu","Wabelane ngawo, kuba abasebenzi benkxaso baqinisekisiwe","Wabelane ngamagama okuqala ama-6 kuphela ukuze ukhuseleke","Bacele ukuba baqale bakuthumelele i-imeyile, uze wabelane ngawo"]}},"38":{"title":"IBhosi ye-Crypto","desc":"Umatshini wexesha we-Bitcoin","content":"Lifikile ixesha lebali elicatshulwa ngumntu wonke kodwa lingaxelwa kakuhle namnye.\\n\\nEkuqaleni kuka-2017, i-Bitcoin enye yayibiza malunga ne-$1,000. NgoDisemba ka-2024 yagqitha kwi-$100,000 okokuqala. Ukuthenga kwe-$1,000, ukubanjwa yonke loo ndlela, kwaba malunga ne-$100,000. Oko kukuphindwa kalikhulu. 🤯\\n\\nNantsi ke inxalenye eshiywa ngumdla: ukuze uqokelele oko kuphindwa kalikhulu kwafuneka uhlale phakathi kokuwa okubini okumasikizi, okunye malunga nama-84% okunye malunga nama-77%, uze ubukele imali yakho incipha IMINYAKA ngexesha ungathengisi. Phantse akakho owakwazi ukuyenza loo nto. Uninzi lwabantu lwathenga phezulu, lwangcangcazela ekuweni, lwaza lwathengisa ezantsi.\\n\\nKwaye kwi-Bitcoin nganye kukho amawaka eengqekeza ezifileyo eziye kwiqanda. Ukukhetha ophumeleleyo kwangaphambili kubonakala kulula xa ujonga umva kuphela. Oko kubizwa ngokuba kukukhetha abasindileyo kuphela, kwaye yeyona nkohliso ibiza kakhulu kwi-crypto.\\n\\nEsona sifundo somatshini wexesha: kwiingqekeza ezasindayo, umonde wabetha ukukhetha ixesha. Kodwa ufumanisa ukuba zeziphi iingqekeza ezisindayo EMVA nje kokwenzeka, yiyo loo nto ukusasaza kubetha ukukhetha iqhawe elinye, kwaye kungoko kungekho MNTU oyaziyo ikamva. Kwanebhosi ngokwayo. 🐉","bossVictory":"Icandelo le-crypto loyisiwe. Ngoku wazi ngaphezu kwabantu abadala abaninzi. 🐉","quiz":{"q":"Amawaka eengqekeza asungulwa kunye ne-Bitcoin, kwaye uninzi lwazo ngoku aluxabisi nto. Kutheni ukuthi \\"khetha nje i-Bitcoin elandelayo\\" kubonakala kulula kangaka xa ujonga umva?","options":["Kuba ngabaphumeleleyo kuphela abasathethwa ngabo, kwaye ezo zafayo zanyamalala ebalini","Kuba ezona ngqekeza zilungileyo zicaca kwasekuqaleni ukuba ufunda ngokwaneleyo","Kuba uninzi lweengqekeza lugqibela lulungile ukuba uzibamba ixesha elide ngokwaneleyo","Kuba oochwepheshe bayiqikelela kakuhle i-Bitcoin ngo-2010"]}},"39":{"title":"Iyintoni Ngokwenene iBlockchain?","desc":"Itekhnoloji ephantsi kwako konke","content":"Susa umdla ogqithisileyo uze ubone ukuba i-blockchain ilula ngokumangalisayo: yincwadi yerekhodi eyabelwanwayo eneekopi ezifanayo ezigcinwa ziikhompyutha ezingamawaka.\\n\\nXa umntu ethumela i-crypto, loo ntengiselwano ingena 'kwibhloko' kunye namakhulu amanye. Ibhloko itywinwa ngemathematika ize ikhonkxwe kwibhloko engaphambili. Kungoko ke: block. Chain. ⛓️\\n\\nKutheni umntu ekhathala? Ngenxa yoko ikwenza kube nokwenzeka:\\n\\n✅ Akakho onokuyihlela imbali ngokuzolileyo. Ukutshintsha ibhloko endala kuya kuthetha ukwenza kwakhona zonke iibhloko ezilandelayo kwiikhompyutha ezingamawaka ngaxeshanye.\\n✅ Ayikho inkampani enye okanye urhulumente oyiqhubayo. Uthungelwano lweekhompyutha luyiqhuba kunye.\\n✅ Nabani na unokujonga irekhodi. Yonke intengiselwano ye-Bitcoin eyakha yenziwa iyabonwa esidlangalaleni.\\n\\nLeyo yitekhnoloji entsha ngokwenene. Kwakhona AYISIYOMALI yemilingo. Irekhodi egqibeleleyo yengqekeza engenaxabiso isengqekeza engenaxabiso. Ukuba itekhnoloji iyinyani akwenzi ukuba yonke ingqekeza eyakhelwe kuyo ibe nexabiso. 🧠","quiz":{"q":"Kutheni kunzima kangaka ukutshintsha ngasese intengiselwano endala kwi-blockchain?","options":["Kuba urhulumente uvuma utshintsho ngalunye","Kuba kuya kufuneka wenze kwakhona zonke iibhloko ezilandelayo kwiikhompyutha ezingamawaka ngaxeshanye","Kuba iintengiselwano ziyacinywa emva kwenyanga","Kuba ngumdali wengqekeza kuphela onokuyihlela irekhodi"]}},"40":{"title":"I-Bitcoin Nazo Zonke Ezinye","desc":"Azifani zonke iingqekeza","content":"'I-Crypto' ayisiyonto inye. Umahluko ubaluleke ngaphezu kokufana:\\n\\n₿ I-BITCOIN: yeyokuqala. Isibonelelo sayo simiselwe kwizigidi ezingama-21 zeengqekeza ngonaphakade, kubhaliwe kwikhowudi, kwaye izinga leengqekeza ezintsha lehla ngesiqingatha malunga neminyaka emine nganye. (Kuvakala kwaziwa? Ukwehla ngesiqingatha kwe-NOOB kuboleke kanye le ngcinga.) Yonke into ezikhankanya ngayo kukunqaba kunye nokhuseleko.\\n\\n⟠ I-ETHEREUM: ayisiyo 'igolide yedijithali' kangako, ngu-'khompyutha wehlabathi' ngakumbi. Iqhuba izivumelwano ezikrelekrele, eziziinkqubo ezizenzekelayo. Uninzi lwee-app ze-crypto zakhelwe kuyo okanye kubakhuphisani bayo.\\n\\n🪙 ZONKE EZINYE: amawaka ee-'altcoin'. Ezimbalwa zisombulula iingxaki zokwenene. Uninzi zizikopi, ngamalinge, okanye kukuqwenga imali. Inani elikhohlakeleyo: uninzi lweengqekeza ezakha zadalwa sele zifile okanye zingenaxabiso.\\n\\nIsifundo: ukuthi 'i-crypto iyanyuka' akukuxeleli nto phantse ngayo NAYIPHI NA ingqekeza ethile. Nganye yibhethi yayo, inamathuba ayo. 🎲","quiz":{"q":"Sithini esona sibonelelo siphezulu se-Bitcoin, kwaye singatshintshwa lula?","options":["Zizigidi ezili-100, kwaye abambi bayavota ngazo minyaka le","Akukho mda ophezulu, iingqekeza ezintsha ziyashicilelwa ngonaphakade","Yibhiliyoni enye, njenge-NOOB","Zizigidi ezingama-21, zimiselwe kwikhowudi, kwaye kuphantse kungenzeki ukuzitshintsha"]}},"41":{"title":"Iingqekeza Ezizinzileyo","desc":"I-crypto ezama ukuma ngxi","content":"Ingqekeza ezinzileyo yi-crypto eyilelwe ukuba ihlale ixabisa isixa esimiselweyo, ngokuqhelekileyo idola elinye lase-US kanye. Abarhwebi bazisebenzisa njengendawo yokupaka: thengisa iingqekeza zakho eziguquguqukayo uzifake kwingqekeza ezinzileyo, imali yakho ihlale ngxi ngelixa ugqiba inyathelo elilandelayo.\\n\\nZihlala njani kwi-$1? Uyilo oluphambili lugcina iidola nezinto zokwenene kubuncwane, ukuze ingqekeza nganye ixhaswe yinto ethile. Uthemba lowo ubambe obo buncwane.\\n\\nNali ke ibali lakho lokulumkisa: iingqekeza ezizinzileyo zinako UKWAPHUKA. Kwenzekile ngokwenene. Ngo-2022 ingqekeza enkulu ezinzileyo 'ye-algorithm', eyayisebenzisa imathematika ekrelekrele endaweni yobuncwane bokwenene, yawa isuka kwi-$1 yaya phantse kwiqanda kwiintsuku ezimbalwa yaza yatshabalalisa amashumi eebhiliyoni zeedola. 'Ukuzinza' yinjongo yoyilo, ayisosiqinisekiso.\\n\\nUmthetho oqhelekileyo: okukhona indlela egcina into 'ikhuselekile' ikrelekrele, kokukhona kufuneka uyijonge ngengqalelo. 🔍","quiz":{"q":"Uyintoni owona msebenzi uphambili wengqekeza ezinzileyo?","options":["Ukubamba ixabiso elimiselweyo, ngokuqhelekileyo i-$1, ukuze abarhwebi babe nendawo ezinzileyo yokupaka","Ukukhula ngokukhawuleza kune-Bitcoin","Ukuhlawula inzala ngokuzenzekelayo","Ukufihla iintengiselwano kuwo wonke umntu"]}},"42":{"title":"I-Crypto, iRhafu Nomthetho","desc":"Ewe, imithetho iyasebenza","content":"I-intanethi izele ngabantu abakholelwa ukuba i-crypto yimali engabonakaliyo engenamithetho. Badla ngokufumanisa ngendlela enzima. 😬\\n\\nInyani kumazwe amaninzi, kuquka uMzantsi Afrika:\\n\\n🧾 INZUZO IDLA NGOKURHAFISWA. Thengisa i-crypto ngaphezu koko wawukuhlawulile, ize igunya lerhafu lifune isabelo salo, njengakwizabelo.\\n\\n🪪 AMAQONGA AYAZI UKUBA UNGUBANI. Amaqonga asemthethweni afuna ukuqinisekiswa kwesazisi (kubizwa ngokuba yi-KYC, Yazi uMthengi wakho). Intengiselwano nganye ikwarekhodwa ngokusisigxina kwi-blockchain ngokwayo, into leyo ECHASENE NCAM nokungaziwa.\\n\\n⚖️ ABALAWULI BABANDAKANYEKILE. EMzantsi Afrika, izinto ze-crypto ziphathwa ngokusesikweni njengeemveliso zemali, oko kuthetha ukuba amaqonga azithengisayo kufuneka alandele imithetho yeenkonzo zemali.\\n\\nAkukho nanye kwezi nto isisizathu sokuba wothuke. YISIZATHU sokungawahoyi amazwi omntu othi 'imithetho ayisebenzi kwi-crypto'. Iyasebenza, kwaye ukwenza ngathi ayisebenzi kufaka abantu abadala engxakini enkulu ngokwenene.","quiz":{"q":"Umzala wakho uthi inzuzo ye-crypto ayibonakali kwigunya lerhafu kuba i-crypto ayaziwa. Yintoni engalunganga apho?","options":["Akukho nto, i-crypto ayaziwa ncam","Inzuzo ye-crypto irhafiswa eMelika kuphela","Amaqonga aqinisekisa izazisi kwaye ii-blockchain zirekhoda yonke into ngokusisigxina, kwaye inzuzo idla ngokurhafiswa","Irhafu isebenza kuphela ukuba ukhupha ngaphezu kwesigidi"]}},"43":{"title":"Ukuguquguquka Nemithetho Yokusinda","desc":"Kutheni i-crypto ijikajika kangaka","content":"Usuku olubi kwimarike yezabelo lulu-3%. Usuku olubi kwi-crypto lungama-20%. Kwa-Bitcoin, 'umdala' we-crypto, ilahlekelwe ngaphezu kwe-80% yexabiso layo ngaphezu kwesihlandlo esinye yaza yachacha kamva. Iingqekeza ezincinci zilahlekelwa yi-95% rhoqo zize zingaze zibuye.\\n\\nKutheni ziqhwalela kangaka? I-crypto irhwetshwa yonke imizuzu yosuku ngaphandle kwezimisi, uninzi lwayo ithengwa ngemali ebolekiweyo enyanzelwa ukuba ithengiswe xa kusiwa, kwaye amaxabiso aqhutywa ngamabali neemvakalelo ngaphezu kweengxelo zenzuzo.\\n\\nNantsi ke imithetho yokusinda, ephindwa ngumrhwebi ngamnye onamava:\\n\\n1️⃣ Ungaze ufake imali ongakwaziyo ukuyilahla ngokupheleleyo.\\n2️⃣ Yenza izikhundla zakho zibe ngangobukhulu obungenakuthi intlekele enye ikucime.\\n3️⃣ Gqiba ngendlela yakho yokuphuma PHAMBI kokuba ungene, ngelixa uzolile.\\n4️⃣ Ukoyika ukushiyeka yeyona mvakalelo ibiza kakhulu kwezemali.\\n\\nZiqhelanise nayo yomine kwi-NoobTrader apho iilahleko zizezokudlala. Imikhwa yiyo eyona mbasa. 🏆","quiz":{"q":"Yeyiphi kwezi ngumthetho wokwenene wokusinda kwiimarike eziguquguqukayo?","options":["Phinda kabini isikhundla sakho emva kwelahleko nganye ukuze uyibuyise","Ungaze utyale imali ongakwaziyo ukuyilahla ngokupheleleyo","Ukuguquguquka kuchaphazela iingqekeza ezincinci kuphela, ngoko ezinkulu zikhuselekile","Soloko uthenga xa wonke umntu kwi-social media ethenga"]}},"44":{"title":"Imijikelezo Yomdla Nokoyika Ukushiyeka","desc":"Indlela ephantsi kwako konke ukubhidakala","content":"I-crypto ihamba ngemijikelezo yomdla, kwaye xa sele uyibona le ndlela awusayi kuze uyilibale:\\n\\n📈 Isigaba 1: kwenzeka into yokwenene. Abakholwayo bokuqala bayathenga bethe cwaka.\\n🚀 Isigaba 2: amaxabiso ayanyuka. Amajelo eendaba ayaqaphela. Ifidi yakho izala ngabaphumeleleyo.\\n🎪 Isigaba 3: ukubhidakala. Abaqhubi beeteksi banika amacebo ngeengqekeza. Abantu bayaboleka ukuze bathenge. 'Eli xesha lahlukile.'\\n💥 Isigaba 4: ukuwa. Abafike mva, abathenge ngokona kuphezulu, balahlekelwa kakhulu.\\n🕳️ Isigaba 5: ukuthula. Iiposti zabaphumeleleyo ziyanyamalala. Akakho othetha ngeelahleko zakhe.\\n\\nUkuqhambuka kwee-NFT ngo-2021 kwalandela le nto kanye: izinto zokuqokelela zedijithali zithengiswa ngezigidi phezulu, kwaye kwiminyaka embalwa emva koko uninzi lwazo lwaluxabisa phantse into engekhoyo.\\n\\nIqhinga elikhohlakeleyo lako konke ukubhidakala: lenza ELONA xesha LIBI lokuthenga livakale njengelona lingxamisekileyo lokuthenga. Xa kuvakala kukhuseleke kakhulu ukungena, kuba wonke umntu sele engenile, inzuzo elula idla ngokuba sele iphelile. 🎯","quiz":{"q":"Kumjikelezo womdla oqhelekileyo, ngowuphi umzuzu apho umntu oqhelekileyo eziva enomnqweno onamandla wokuthenga?","options":["Isigaba 1, xa kungekho mntu uthetha ngayo","Ngexesha lokuwa, xa amaxabiso esezantsi kakhulu","Kwenzeka nje ngokungalindelekanga kungalandeli ndlela","Kufuphi nasencotsheni, xa wonke umntu omngqongileyo sele engenile kwaye kuvakala kukhuselekile kakhulu"]}},"45":{"title":"Ukufunda iKhandlela","desc":"Isakhiwo sekhandlela: umzimba nombala","content":"Ikhandlela ngalinye libalisa ibali elincinci ngamanani amane kuphela: apho ixabiso livule khona, elona liphezulu elifikelele kulo, elona lisezantsi liwele kulo, nalapho livale khona. Umzimba oqinileyo usuka ekuvuleni ude uye ekuvaleni, kwaye umbala ukuxelela ukuba ngubani ophumeleleyo: oluhlaza luthetha ukuba ukuvala kugqibele kungentla kokuvula, obomvu buthetha ukuba abathengisi balitsalele ezantsi. Lelo lonke iqhinga. Funda ukulifunda kakuhle ikhandlela elinye uze wonke umzobo ehlabathini utshintshe usuka kudonga lwengxolo ube libali lemifanekiso. 🟢","quiz":{"q":"Eli khandlela liluhlaza. Likuxelela ntoni ngelo xesha lokurhweba?","options":["Ixabiso livale ngaphantsi kokuba livulile","Abantu abaninzi bathengile kunabathengisileyo, kuqinisekisiwe","Ixabiso livale ngaphezu kokuba livulile","Ixabiso alizange lehle kwelo xesha"]}},"46":{"title":"Iintambo Zibalisa Amabali","desc":"Isakhiwo sekhandlela: iindawo eziphezulu nezisezantsi","content":"Umzimba ubonisa apho ixesha livule livale khona, kodwa iintambo zibonisa uhambo lonke: lonke ixabiso umlo owafikelela kulo ngokwenene. Intambo ende ithetha ukuba kwabakho umlo omkhulu ngaphaya kokuvula nokuvala, kwaye icala elashiya intambo lalahlekelwa loo mlo. Intambo ende ezantsi? Abathengisi batyhala kakhulu baza babuyiselwa umva. Intambo ende phezulu? Abathengi bafikelela phezulu baza balelwa. Umzimba ngumxholo, iintambo zizo iindaba ezithethwayo. 📏","quiz":{"q":"Ibonisa ntoni ngokwenene imigca emincinci (iintambo) engentla nangezantsi komzimba?","options":["Elona xabiso liphezulu nelona lisezantsi elirhwetshiweyo ngelo xesha","Ukuvula nokuvala kwayizolo","Amaxabiso kanye apho iintengiselwano ezininzi zenzeka khona","Uqikelelo lomda wangomso"]}},"47":{"title":"IDoji","desc":"Amakhandlela awodwa: ukungagqibi","content":"Ngamanye amaxesha ikhandlela livula lize livale phantse kwixabiso elinye kanye, lishiye umzimba omncinci uneentambo macala omabini. Leyo yidoji, kwaye ithetha ukuba umtsalo wentambo waphela kungekho phumeleleyo: abathengi nabathengisi batsala kakhulu ixesha lonke kodwa akwabakho phumeleleyo. Ngokwayo ayithethi nto ingako. Emva kokubaleka okuqinileyo inokucebisa ukuba utyekelo luyadinwa, kuba icala ebeliphumelela lasilela ngequbuliso ukushukumisa ixabiso. Ngumkhondo ofanele uphawulwe, ungasoze ube sisiqinisekiso. 🤝","quiz":{"q":"Ikhandlela elikhanyayo livule laza lavala phantse kwixabiso elinye kanye. Libizwa ntoni, kwaye licebisa ntoni?","options":["Yimarubozu, umqondiso wokuqiniseka okupheleleyo","Yihamile, umqondiso wokuba abathengi bathathe ulawulo","Ngumsantsa, umqondiso wokuba ukurhweba kumile","Yidoji, umqondiso wokungagqibi phakathi kwabathengi nabathengisi"]}},"48":{"title":"IHamile","desc":"Amakhandlela awodwa: ukubuya emlweni","content":"Yenza umfanekiso wexesha elimasikizi: abathengisi batyhalela ixabiso ezantsi, baze abathengi balibuyisele phezulu lonke phambi kokuvala. Into eseleyo kumzobo yihamile: umzimba omncinci ngasentla onentambo ende ngezantsi ephindwe ubuncinci kabini ubukhulu bawo. Emva kokutyibilika kusiya ezantsi, ihamile ithi abathengisi bazame olona nqindi lwabo lukhulu kodwa aluhlabanga. Oko kudla ngokuphawula utshintsho olunokwenzeka. Olunokwenzeka, kungekhona olwenzekayo ngokuqinisekileyo, ngoko ke yiphathe njengomkhondo omawuwujonge, kungekhona njengomyalelo wokuthenga. 🔨","quiz":{"q":"Emva kokutyibilika kusiya ezantsi, ikhandlela elikhanyayo lishicilele intambo ende ngezantsi kunye nomzimba omncinci ngasentla. Iyintoni?","options":["Yinkwenkwezi ewayo, umqondiso wokuba abathengisi bathathile","Yihamile, umkhondo wokuba abathengi balwe kakhulu bebuyisa","Yidoji, ukulingana okugqibeleleyo","Bubungqina bokuba utyekelo olwehlayo luphelile"]}},"49":{"title":"INkwenkwezi Ewayo","desc":"Amakhandlela awodwa: ukulelwa phezulu","content":"Ngumfanekiso osesipilini wehamile. Emva kokunyuka okuqinileyo, abathengi bafikelela kwenye indawo entsha ephezulu, balelwe kabuhlungu, ize ixabiso livale libuyele ezantsi kufuphi nalapho livule khona. Umzobo ushicilela umzimba omncinci ngezantsi ekhandleleni onentambo ende ngentla: yinkwenkwezi ewayo. Ithetha ukuba abathengisi bafike ekugqibeleni phezulu benamandla aneleyo okuphumelela elo xesha. Emva kokubaleka okukhulu, oko kulelwa kudla ngokubaluleka. Kudla, kungekhona ngamaxesha onke. 🌠","quiz":{"q":"Emva kokunyuka okuqinileyo, ikhandlela elikhanyayo litsibele phezulu laza lavala kufuphi nendawo yalo esezantsi, lishiya intambo ende ngentla. Iyintoni?","options":["Yinkwenkwezi ewayo, umkhondo wokuba abathengisi bafike phezulu","Yihamile, umkhondo wokuba abathengi babuyele ekulawuleni","Yimarubozu eluhlaza, ngamandla okuthenga acocekileyo","Sisiqinisekiso sokuba ixabiso liya kuwa ngomso"]}},"50":{"title":"IMarubozu","desc":"Amakhandlela awodwa: ukuqiniseka okupheleleyo","content":"Imarubozu ngumzimba omnye oqinileyo ongenazo iintambo konke konke: ixabiso livule laza lahamba ngecala elinye ixesha lonke lingaze libheke umva. Akukho mlo, akukho kuthandabuza, kuqiniseka okupheleleyo kwicala elinye. Imarubozu eluhlaza ikhwaza ukuzithemba kwabathengi, ebomvu ikhwaza okuchaseneyo. Zinqabile, yiyo kanye loo nto abarhwebi bevuka bagalele xa kuvela enye. 💪","quiz":{"q":"Ikhandlela elikhanyayo ngumzimba omnye oqinileyo ongenazo iintambo konke konke. Sikuxelela ntoni eso simo?","options":["Akukho mntu owarhwebayo ngelo xesha","Imarike yavala kwangethuba ngaloo mini","Icala elinye lalilawula ukusuka ekuvuleni ukuya ekuvaleni, kuqiniseka okupheleleyo","Abathengi nabathengisi babelingana ncam"]}},"51":{"title":"Ukuginya Kwenkunzi","desc":"Iindlela zamakhandlela amabini: abathengi bayangena","content":"Amakhandlela amabini, umyalezo omnye. Kuqala ikhandlela elincinci elibomvu, into eqhelekileyo kutyekelo olwehlayo. Emva koko umzimba omkhulu oluhlaza oliginya lonke: kwixesha elinye, abathengi bacima yonke into abathengisi abayenzileyo ngemini yangaphambili, kwakunye nokungakumbi. Xa lifika emva kotyekelo olwehlayo, ukuginya kwenkunzi ngomnye wemikhondo yotshintsho ejongwa kakhulu kuwo nawuphi na umzobo, kuba lubonisa amandla etshintsha icala ngekhandlela elinye. Ngumkhondo, ayisosivumelwano. 🐂","quiz":{"q":"Umzimba omkhulu oluhlaza uwuginya ngokupheleleyo umzimba obomvu ophambi kwawo. Yeyiphi le ndlela yamakhandlela amabini?","options":["Kukuginya kwebhere, abathengisi bathathe ulawulo","Kukuginya kwenkunzi, abathengi boyise abathengisi","Sisiseko esiphindwe kabini","Zii-doji ezimbini ezilandelelanayo"]}},"52":{"title":"Ukuginya Kwebhere","desc":"Iindlela zamakhandlela amabini: abathengisi bayangena","content":"Ngumfanekiso osesipilini wowenkunzi. Encotsheni yokunyuka, umzimba omkhulu obomvu uginya wonke umzimba oluhlaza ophambi kwawo: abathengisi bacima ukuthenga kwemini engaphambili ngekhandlela elinye, kanye apho ukunyuka bekusele kolulekile nalapho abathengi bakutshanje bebexhalabile. Oko kudla ngokwenza nabanye abathengi baxhalabe. Xa uyibona emva kokubaleka okude, yihloniphe. 🐻","quiz":{"q":"Encotsheni yokunyuka, umzimba omkhulu obomvu uginya wonke umzimba oluhlaza ophambi kwawo. Ibizwa ntoni le pere?","options":["Kukuginya kwenkunzi, ukunyuka kuyaqhubeka","Yihamile ilandelwa yidoji","Kukuqhawuka kungentla komqobo","Kukuginya kwebhere, abathengisi boyise abathengi"]}},"53":{"title":"Ukubona uTyekelo Olunyukayo","desc":"Utyekelo: iincopho eziphakamayo, neendawo ezisezantsi eziphakamayo","content":"Utyekelo olunyukayo lufuna zombini iinxalenye: iincopho eziphakamayo NEENDAWO ezisezantsi eziphakamayo. Incopho nganye ibetha eyangaphambili, kwaye ukwehla ngakunye kumisa phezulu kunokwangaphambili, kuba abathengi behlala bengena kwangoko qho. Olo milo lwezitepsi yimarike ikuxelela ukuba imfuno iyalawula. Incopho enye ephakamileyo yodwa ayingqini nto. Indlela yiloo pere, iphindaphindeka. 📈","quiz":{"q":"Incopho nganye ibetha eyangaphambili, kwaye ukwehla ngakunye kumisa phezulu kunokwangaphambili. Ubonisa ntoni lo mzobo?","options":["Lutyekelo olunyukayo, iincopho eziphakamayo neendawo ezisezantsi eziphakamayo","Lutyekelo olwehlayo, iincopho ezisezantsi neendawo ezisezantsi ezehla ngakumbi","Ngumda, ixabiso libambeke phakathi komgangatho nosilingi","Yincopho ephindwe kabini eqhubekayo"]}},"54":{"title":"Ukubona uTyekelo Olwehlayo","desc":"Utyekelo: iincopho ezisezantsi, neendawo ezisezantsi ezehlayo","content":"Guqula izitepsi zibheke phantsi. Iincopho ezisezantsi zithetha ukuba abathengisi bahlasela kwangoko kudlobo ngalunye, iindawo ezisezantsi ezehla ngakumbi zithetha ukuba abathengi barhoxa ngakumbi ekwehleni ngakunye. Lo gama olo lwakhiwo lubambile, ngabathengisi abaqhuba umdlalo, kwaye ukulwa nabo yindlela abarhwebi abatsha abanikela ngayo ngemali kwabo banomonde. Utyekelo alusotshaba lwakho, kodwa ukwenza ngathi alukho ngokuqinisekileyo kulutshaba. 📉","quiz":{"q":"Udlobo ngalunye luphelela ezantsi kunolwangaphambili, kwaye ukwehla ngakunye kusika nzulu ngakumbi. Ujonge ntoni?","options":["Lutyekelo olunyukayo oluphefumlayo","Ngumda ohamba ecaleni","Lutyekelo olwehlayo, iincopho ezisezantsi neendawo ezisezantsi ezehla ngakumbi","Yindlela yokuginya kwenkunzi"]}},"55":{"title":"Imarike Ehamba Ecaleni","desc":"Utyekelo: umdlalo wokulinda","content":"Ngamanye amaxesha akukho cala liphumelelayo, ngoko ke ixabiso liyatsibatsiba nje phakathi komgangatho omnye nosilingi omnye iiveki ezininzi. Lowo ngumda, kwaye iimarike zichitha inxalenye enkulu yobomi bazo zisenza kanye oku. Ayonakalanga kwaye ayidiki, yimarike ephefumlayo. Abarhwebi abanomonde bafunda ukukuthanda ukulinda, kuba okukhona umda uhlala ixesha elide, kokukhona ukuphuma kwawo ekugqibeleni kudla ngokubaluleka ngakumbi. 🏓","quiz":{"q":"Iiveki ngeeveki ixabiso lidlobe phakathi komgangatho omnye nosilingi omnye. Kubizwa ntoni oku?","options":["Lutyekelo olunyukayo, lihlala lichukumisa usilingi","Ngumda, imarike ihamba ecaleni","Yintloko namagxa","Kukuqhawuka okuqhubekayo"]}},"56":{"title":"Inkxaso","desc":"Inkxaso nomqobo: umgangatho","content":"Xa ixabiso lihlala lisehla lisiya kwinqanaba elinye lize lidlobe qho, abarhwebi babiza elo nqanaba ngokuba yinkxaso: ngumgangatho apho abathengi behlala begqiba ukuba ixabiso litshiphu. Okukhona libambelela izihlandlo ezininzi, kokukhona abantu abaninzi belijonga, nto leyo eyinxalenye yesizathu sokuba lihlale libambelela. Kodwa khumbula ukuba umgangatho uzotywa ngabantu, kungekhona ngumthetho. Inkxaso ingaqhawuka kwaye iyaqhawuka, kwaye xa kusenzeka oko, isihlwele ebesilindele udlobo siba sisihlwele esingcangcazelayo. 🧱","quiz":{"q":"Ixabiso lehlele kwinqanaba elimnyama izihlandlo ezithathu, laza ladloba ngesihlandlo ngasinye. Abarhwebi balibiza ntoni elo nqanaba?","options":["Ngumqobo, usilingi apho abathengisi begcwala khona","Ngumgca wotyekelo, amanqanaba kufuneka athe tyaba","Sisimisi-lahleko esimiselwe liqonga","Yinkxaso, ngumgangatho apho abathengi behlala bengena khona"]}},"57":{"title":"Umqobo","desc":"Inkxaso nomqobo: usilingi","content":"Umqobo ngusilingi: linqanaba apho ukunyuka ngakunye kuhlala kunqumama khona kuba abathengisi bevuya ukuthatha imali yabo apho. Bukela umzobo ubetha intloko yawo kwixabiso elinye izihlandlo ezithathu uze ubukele umqobo usebenza ngoku nangoku. Nantsi into efanele ikhunjulwe: ukuba ixabiso liyakhe liqhawule lidlule ngenkuthalo yokwenene, loo silingi umdala udla ngokuqala ukuziphatha njengomgangatho omtsha. 🪟","quiz":{"q":"Ukunyuka okuthathu okwahlukeneyo kunqumame kwinqanaba elimnyama. Libizwa ntoni elo nqanaba?","options":["Ngumqobo, usilingi apho abathengisi behlala betyhalela emva khona","Yinkxaso, ngumgangatho ophantsi kwexabiso","Linqanaba ledividendi","Kukudubula komthamo"]}},"58":{"title":"Imigca yoTyekelo","desc":"Imigca yotyekelo nemijelo: umgca obalulekileyo","content":"Dibanisa iindawo ezisezantsi ezinyukayo kumzobo uze ube uzobe umgca wotyekelo. Naziphi na iindawo ezimbini zenza umgca, kodwa ukuchukumisa kwesithathu kulapho uqala ukungqina ukuba ubalulekile, kuba kubonisa ukuba abathengi bahlala belikhusela inqanaba elinye elinyukayo. Ukuchukumisa ngakunye okongezelelweyo okuhlonitshwayo bubungqina obungakumbi. Buhlala bubungqina, abusoze bube sisithembiso: umgca wotyekelo luphawu lwepensile, awungomnatha wamandla. ✏️","quiz":{"q":"Lo mgca unyukayo uchukunyiswe izihlandlo ezithathu ezahlukeneyo. Kutheni abarhwebi bekhathala ukuba umgca wotyekelo uchukunyiswe kangaphi?","options":["Abakhathali, naziphi na iindawo ezimbini zenza umgca wotyekelo ube ngumthetho","Ukuchukumisa okuthathu kuthetha ukuba udlobo lwesine luqinisekisiwe","Ukuchukumisa okungakumbi kwenza umgca ubaluleke ngakumbi, abathengi bahlala bewukhusela","Imigca yotyekelo ibalulekile kwimizobo yemihla ngemihla kuphela"]}},"59":{"title":"Imijelo","desc":"Imigca yotyekelo nemijelo: umendo","content":"Umjelo lutyekelo olunembeko. Ixabiso liyanyuka lidloba phakathi kwemigca emibini ehambelanayo: umgangatho weendawo ezisezantsi ezinyukayo nosilingi weencopho ezinyukayo, zihamba phezulu kunye njengamacala omendo. Abarhwebi bajonga onke amaphethelo befuna udlobo, kwaye bajonga ngakumbi usuku ixabiso eliphuma ngalo emendweni, kuba ukuqhawuka okucacileyo kumjelo kudla ngokuba yindawo apho ushukumo olukhulu olulandelayo luqala khona. 🛣️","quiz":{"q":"Ixabiso liyanyuka lidloba phakathi kwemigca emibini ehambelanayo. Yeyiphi le ndlela?","options":["Ngunxantathu, imigca kufuneka idibane","Ngumjelo onyukayo, lutyekelo olunyukayo olunomendo obonakalayo","Yincopho ephindwe kabini","Ngumda othe tyaba"]}},"60":{"title":"INcopho Ephindwe Kabini","desc":"Iindlela zomzobo: umilo we-M","content":"Ixabiso libetha usilingi omnye kabini, lisilela zombini izihlandlo, lize lizobe u-M omkhulu kumzobo. Qhawula ngezantsi kokwehla okuphakathi (umqala) size esi sincopho siphindwe kabini sigqitywe: ngumkhondo oqhelekileyo wotshintsho olwehlayo. Umfanekiso waso osesipilini, u-W, sisiseko esiphindwe kabini, kwaye sikhomba kwelinye icala. Sidla ngokuphawula incopho, kodwa akunyanzelekanga. Akukho nto ikumzobo enyanzelekileyo. Ⓜ️","quiz":{"q":"Ixabiso libethe usilingi omnye kabini, lasilela zombini izihlandlo, laza laqhawula ngezantsi kokwehla okuphakathi. Yeyiphi le milo?","options":["Sisiseko esiphindwe kabini, ngumkhondo wenkunzi","Ngumjelo onyukayo","Yihamile","Yincopho ephindwe kabini, ngumkhondo wotshintsho lwebhere"]}},"61":{"title":"Xa Iindlela Zisilela","desc":"Iindlela zomzobo: amathuba, kungekhona izithembiso","content":"Esi sesona sifundo sixabisekileyo kweli candelo. Kwavela indlela efana ncam neyencwadi, wonke umntu wayibona, yaza imarike yenza okuchaseneyo. Zonke iindlela ozifundileyo ziyasilela ngamanye amaxesha, kwaye oko akungomzobo ukuxokisa, ngumzobo okunika ulwazi: icala obulixhasa lisandul' ukulahlekelwa. Gqiba ngendlela yakho yokuphuma phambi kokuba ungene, kwaye xa indlela isilela, thabatha umkhondo uphume. Iindlela ngamathuba, azisoze zibe zizithembiso. 🚪","quiz":{"q":"Kwavela isiseko esiphindwe kabini sencwadi kumgangatho omnyama... laza ixabiso lawa lawuqhawula ngqo. Sithini isifundo esinyanisekileyo?","options":["Iindlela ngamathuba, kungekhona izithembiso, kwaye indlela esilelayo ngumqondiso wakho wokuphuma","Iziseko eziphindwe kabini zokwenyani azisoze zisilele, ngoko esi besingesiso esokwenyani","Thenga ngakumbi, indlela isaya kwenzeka ekugqibeleni","Imizobo iyayeka ukusebenza xa indlela isilela"]}},"62":{"title":"Intloko Namagxa","desc":"Iindlela zomzobo: iincopho ezintathu","content":"Iincopho ezintathu: ende phakathi (intloko), ephantsi macala omabini (amagxa), nomgca ophantsi kokwehla okubini obizwa ngokuba ngumqala. Yenzeka xa abathengi bekwazi ukutyhala okunye kokugqibela okuphezulu baze bangakwazi nokukulinganisa kwilinge elilandelayo. Umilo wodwa sisilumkiso kuphela. Into abarhwebi abayilindayo ngokwenene kukuqhawuka okugqibeleleyo ngezantsi komqala, kuba kulapho indlela iyeka khona ukuba ngumzobo iqale ukuba sisigqibo. 👤","quiz":{"q":"Iincopho ezintathu: ende phakathi, ephantsi macala omabini, nomgangatho odibanisa ukwehla okubini. Yeyiphi le milo iqhelekileyo?","options":["Sisiseko esiphindwe kathathu","Yintloko namagxa, ukuphela okunokwenzeka kotyekelo olunyukayo","Ngunxantathu onyukayo","Ziihamile ezintathu ezilandelelanayo"]}},"63":{"title":"Ukuxinana Konxantathu","desc":"Iindlela zomzobo: intsimbi esongiweyo","content":"Xa ukujikajika kuhlala kuncipha, iindawo ezisezantsi eziphakamayo zicinezela iincopho ezisezantsi, imarike isonga njengentsimbi. Lowo ngunxantathu: onke amacala aphelelwa yindawo, kunyanzelwa isigqibo. Ukuxinana kudla ngokuphela ngokuqhuma, kwaye nantsi into: icala lokuqhuma alaziwa kwangaphambili. Linda ukuqhawuka endaweni yokuqikelela. Imarike iza kukuxelela, kwaye ayibizi nto ngolo lwazi. 🌀","quiz":{"q":"Ukujikajika kuhlala kuncipha, kuxina ixabiso kwisonga elixineneyo ngakumbi, de ekugqibeleni liqhume liphume. Ibiyintoni loo nto isongiweyo?","options":["Ngumjelo, imigca ayisoze idibane","Yincopho ephindwe kabini","Ngunxantathu, kukudibana okudla ngokuphela ngokuqhawuka","Bubungqina bokuba ixabiso beliza kunyuka"]}},"64":{"title":"Umthamo: Isifumanisi-buxoki","desc":"Umthamo: ngubani ofike ngokwenene","content":"Umthamo zizabelo ezingaphi ezatshintsha izandla, kwaye sisifumanisi-buxoki semizobo. Ukuqhawuka ngomthamo omncinci sisisebezo esilahlekisa abantu: iintengiselwano ezimbalwa zatyhala ixabiso laya kwindawo elingenakuhlala kuyo. Ukuqhawuka ngomthamo omkhulu sisihlwele esivota ngokwenene ngemali. Ushukumo olunye lwexabiso, intsingiselo eyahluke ngokupheleleyo. Phambi kokuba ukholelwe naluphi na ushukumo olukhulu, jonga ukuba ngubani ofike kulo. 🔊","quiz":{"q":"Amalinge amabini okuphuma kusilingi omnye: elokuqala ngomthamo omncinci lasilela, elesibini leza nomthamo omkhulu labambelela. Wenza ntoni umthamo apha?","options":["Akukho nto, umthamo awuze ubaluleke","Unyanzela ixabiso linyuke, umthamo ophezulu utyhala amaxabiso","Uqikelela kanye incopho yoshukumo","Usebenza njengesiqinisekiso, umthamo omkhulu ubonisa ukuqiniseka kokwenene emva koshukumo"]}},"65":{"title":"Isibonisi soTyekelo","desc":"Imizobo elishumi, akukho malebhile, akukho nceba","content":"Imizobo elishumi. Akukho malebhile, akukho migca yoncedo, akukho macebo. Chaza ukuba ngamnye ubonisa ntoni, kanye njengomrhwebi wokwenene ojonge kwiscreen sokwenyani. Fumana i-8 kwili-10 uze icandelo libe lelakho. Ufumana ilinge elinye ngosuku, ngoko ke cotha, ufunde amakhandlela, uze ukhumbule esona sifundo sibaluleke ngaphezu kwazo zonke: ngamanye amaxesha impendulo enyanisekileyo kukuba akukho ndlela ikhoyo kwaphela. 🕯️","bossVictory":"Icandelo lotyekelo loyisiwe. Ngoku uyayifunda imizobo, imizobo ayikufundi wena. 🕯️","bossQuestions":{"0":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Ubhixekile ngabom. Susa ingxolo uze ubone ukuba incopho nganye isabetha eyangaphambili, kwaye ukwehla ngakunye kusaphelela phezulu ngakumbi. Utyekelo lokwenene lukhangeleka ngolu hlobo, kungekhona njengezitepsi zencwadi.","options":["Lutyekelo olwehlayo, iincopho ezisezantsi neendawo ezisezantsi ezehla ngakumbi","Lutyekelo olunyukayo, iincopho eziphakamayo neendawo ezisezantsi eziphakamayo","Ngumda ohamba ecaleni","Yincopho ephindwe kabini"]},"1":{"q":"Kwenzeke ntoni kwipere yamakhandlela ekhanyayo?","explanation":"Umzimba obomvu uginye wonke umzimba oluhlaza emva nje kokunyuka okude. Kukuginya kwebhere kusenza kanye into ekwenzayo: kuvela apho abathengi bolulwe khona ngokugqithisileyo.","options":["Kukuginya kwenkunzi","Yidoji phezulu","Yihamile","Kukuginya kwebhere encotsheni yokunyuka"]},"2":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Incopho ephakathi imi ngokucacileyo ngaphezu kwezimbini ezisemacaleni, kwaye ukwehla kudibana kwenze umqala. Ezokwenyani azisoze zilingane macala omabini, kwaye ngolu hlobo ezikhangeleka ngalo ngokwenene.","options":["Yintloko namagxa","Yincopho ephindwe kathathu eneencopho ezintathu ezilinganayo","Ngunxantathu onyukayo","Ngumjelo onyukayo"]},"3":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Amalinge amabini okungena kumgangatho omnye, elesibini lingaphantsi kancinci, kwaza kwabakho ukutyhalela phezulu kudlula udlobo oluphakathi. Umilo we-W, uzotywe yimarike yokwenene endaweni yencwadi.","options":["Yintloko namagxa","Ngunxantathu owehlayo","Sisiseko esiphindwe kabini","Yiflegi yebhere"]},"4":{"q":"Liyintoni ikhandlela elikhanyayo?","explanation":"Intambo ende ngentla, umzimba omncinci umi ezantsi komda, emva nje kokunyuka. Abathengi bafikelela kwindawo entsha ephezulu baza babuyiselwa ezantsi phambi kokuvala.","options":["Yihamile","Yimarubozu eluhlaza","Yidoji","Yinkwenkwezi ewayo emva kokunyuka"]},"5":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Umgangatho omnye nosilingi omnye bahlala behlonitshwa, kwaye yonke into ephakathi yingxolo. Akukho cala liphumelelayo, ngoko ke akukho tyekelo lokukhwela.","options":["Ngumda, ixabiso livalelwe phakathi kwenkxaso nomqobo","Lutyekelo olunyukayo, iincopho eziphakamayo neendawo ezisezantsi eziphakamayo","Sisikhonkwane esehlayo","Kukuqhawuka okuqhubekayo"]},"6":{"q":"Ixabiso liqhawule ladlula usilingi omdala, laza ukwehla okukhonjwa ngutolo kwabuyela kwelo nqanaba kwaza kwabambelela. Kwakuyintoni oko kwehla?","explanation":"Ukwehla kwabuyela kanye kwinqanaba elalikade lingusilingi, kwafumana abathengi apho, lwaza utyekelo lwaqhubeka. Oko kukubuyela umva okuncinci. Utshintsho lwalusiya lusika ludlule kwinqanaba luze luqhubeke lusiwa.","options":["Lutshintsho olupheleleyo olusiya kutyekelo olwehlayo","Kukubuyela umva okuncinci, ukuvavanywa kwakhona kwenqanaba eliqhawukileyo","Yincopho ephindwe kabini","Ludlobo lobuxoki oluza kulandelwa kukuwa"]},"7":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Umgangatho othe tyaba, iincopho ezisezantsi zicinezela phezu kwawo, abathengisi befika kwangoko kudlobo ngalunye. Umgangatho ekugqibeleni wanikezela, olo lolona phumo lo milo udla ngokutyekela kulo. Udla, kungekhona ngamaxesha onke.","options":["Ngunxantathu onyukayo","Ngumjelo onyukayo","Ngunxantathu owehlayo oyame enkxasweni","Sisiseko esiphindwe kabini"]},"8":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Ngumbuzo womgibe, kwaye ngowona ubaluleke ngakumbi kwibhosi. Uninzi lwemizobo, amaxesha amaninzi, alubonisi nto ifanele ukurhwetshwa. Ukubona iindlela ezingekhoyo yindlela abaqalayo abalahlekelwa ngayo. Ukuthi akukho ntengiselwano sisakhono. 🎯","options":["Yintloko namagxa","Yincopho ephindwe kabini","Lutyekelo olunyukayo","Akukho ndlela icacileyo, akukho nto irhwetshwayo apha"]},"9":{"q":"Ubonisa ntoni lo mzobo?","explanation":"Ixabiso litshole ngentla kosilingi ngomthamo obuthathaka, abathengi balisukela, laza labuyela ngqo emdeni liwa. Ukuqhawuka okusilelayo kungqina kanye isizathu sokuba isifundo somthamo sikuxelele ukuba ujonge umthamo phambi kokuba ukholelwe kuko.","options":["Ngumgibe wenkunzi, kukuqhawuka okusilelayo okwatsala abathengi","Kukuqhawuka okuphumeleleyo okunovavanyo olucacileyo","Sisiseko esiphindwe kabini","Lutshintsho lwehamile"]}}},"66":{"title":"Apha Akukho Nto Uyiyo Eyakho","desc":"I-derivative yibhethi kwinani","content":"Yonke into oyifundileyo kude kube ngoku ibinento ngasemva kwayo. Thenga isabelo sika-{retail} uze ube ngumnini wecandelo lenkampani: icandelo leevenkile, icandelo lenzuzo, ivoti kwintlanganiso, nedividendi xa behlawula.\\n\\nI-derivative asiyiyo loo nto.\\n\\nI-CFD (isivumelwano somahluko) sisivumelwano phakathi kwakho nomboneleli sokutshintshiselana ngomahluko wexabiso phakathi kokuvula nokuvala kwakho. Yiyo yonke loo mveliso. Ukuba u-{retail} uyanyuka kwaye ubhejile ukuba uyanyuka, bakuhlawula umahluko. Ukuba uyehla, wena ubahlawula bona. Akukho mntu uthenga isabelo. Akukho mntu uthengisa isabelo. Akukho zabelo zikhoyo naphi na kule ntengiselwano.\\n\\nI-future sisivumelwano sokuthenga okanye ukuthengisa into ngexabiso elimiselweyo ngomhla omiselweyo. Ezokwenyani zihlawulwa ngeedrom zeoyile okanye ngeetoni zombona, kodwa phantse akakho ozibamba ixesha elide kangako, ngoko ke enyanisweni uninzi lwee-future zikwayibhethi kwinani elinomhla wokugqibela.\\n\\nKutheni oku kubaluleke ngaphezu kokuvakala kwako:\\n\\n• Akukho zidividendi. Akukho Ntsana zeMali. Into eyakha inxalenye enkulu yembuyekezo kwisifundo 15 ayikho apha kwaphela.\\n• Akukho voti, akukho bunini, akukho nto yokubamba. Akukho khetho lokuthi \\"yibambe nje iminyaka elishumi\\", kuba akukho nto yokubamba.\\n• Akukho nzala idibeneyo. Yonke le app ichitha izifundo ezingama-65 ikufundisa ukuba ixesha likwicala lakho. Kule gumbi, ixesha likubiza imali. Uza kubona ukuba lingakanani kwisifundo 72.\\n\\nYonke into osele uyazi isabalulekile. Iyeka nje ukuba yiyo into oyenzayo. 📄","quiz":{"q":"Uvula i-CFD ku-{retail} lize ixabiso linyuke. Ngumnini wantoni ngokwenene?","options":["Izabelo ku-{retail}, ezibanjelwe wena ngumboneleli","Isabelo ku-{retail} kunye nelungelo lakuyo nayiphi na idividendi ayihlawulayo","Akukho nto. Ubambe isivumelwano sokutshintshiselana ngomahluko wexabiso, kwaye akukho zabelo zitshintsha izandla","Yivawutsha eguqukela kwizabelo zokwenyani xa uvala"]}},"67":{"title":"Ukuboleka Kumhlobo","desc":"Iyintoni i-leverage ngokwenene, nenxalenye engaposwa mntu","content":"I-leverage ivakala inobuchule. Ayinjalo. Kukuboleka.\\n\\nMasithi ufuna izabelo ze-{c}1,000 kodwa une-{c}200 kuphela. Umhlobo uzinikela ukufaka enye i-{c}800. Ulawula izabelo ze-{c}1,000 nge-{c}200 yemali yakho. Yiyo leyo i-leverage. Yiyo yonke le ngcinga.\\n\\nNgoku zintathu izinto azenzayo loo mhlobo. Uzifuna zontathu, okanye uthengiselwe intsomi.\\n\\n1️⃣ INZUZO IYEYAKHO NGOKWENENE. Izabelo zinyuka nge-10%. I-{c}1,000 yakho ngoku yi-{c}1,100. Leyo yi-{c}100 yenzuzo kwaye ugcina yonke isenti yayo, kuba umhlobo wakho utyalwa i-{c}800 kuphela hayi ne{cName} ngaphezulu. Kwi-{c}200 yakho, i-{c}100 yinzuzo eyi-50%. Ushukumo lwe-10% lukwenzele i-50%. Yile nxalenye wonke umntu ayiposayo.\\n\\n2️⃣ ITYALA ALINCIPHI XA UNGACHANANGA. Le yinxalenye engaposwa mntu, kwaye sisifundo siphela. Izabelo zehla nge-10% endaweni yoko. I-{c}1,000 yakho ngoku yi-{c}900. Usalityala umhlobo wakho i-{c}800 ipheleleyo. Hayi i-{c}720. I-{c}800 ipheleleyo. Ngoko ke yonke i-{c}100 yokwehla iphuma KWISABELO SAKHO, kwaye i-{c}200 yakho ngoku yi-{c}100. Ushukumo lwe-10% lukubize i-50%.\\n\\nZifunde kwakhona ezo zimbini. Umhlobo omnye, i-10% enye. Imali yakho ihamba ngesantya esiphindwe kahlanu kumacala omabini, kuba ityala alize lithathe isabelo sentlungu.\\n\\n3️⃣ UMHLOBO UBIZA IRENTE, MIHLA LE, KUYO YONKE INTO. Kungekhona kwi-{c}800 yakhe. Kwi-{c}1,000 epheleleyo oyilawulayo. Bonke ubusuku oyibambileyo, nokuba ixabiso linyukile, lehlile, okanye lingayanga ndawo.\\n\\nKwaye kukho into yesine ifihlakele ngaphakathi kweyesithathu. Ukuba i-{c}200 yakho iyaphela, umhlobo wakho akakufowuneli ukuze nithethe ngayo. Uyathengisa. Ngoko nangoko, ngokuzenzekelayo, nangaliphi na ixabiso elifumanekayo, kuba yi-{c}800 yakhe esemngciphekweni kwaye akalulindanga uluvo lwakho. Loo nto inegama, kwaye uza kudibana nayo kwizifundo ezintathu ezizayo: i-liquidation.\\n\\nNgoko ke: inzuzo enkulu ngakumbi, iilahleko ezinkulu ngakumbi, irente bonke ubusuku, nomnye umntu onomnwe kwiqhosha lokuthengisa. I-leverage ayisiyomali yasimahla enomngcipheko omncinci. Lityala elinazo zone ezo zinto, kwaye iintengiso zikubonisa eyokuqala kuphela. 🧠","quiz":{"q":"Umhlobo wakho ufaka i-{c}800, wena ufaka i-{c}200, kwaye kunye nilawula izabelo ze-{c}1,000. Izabelo zehla nge-10%. Kwenzeka ntoni kwi-{c}200 yakho?","options":["Yehla ibe yi-{c}100, kuba ityala le-{c}800 alinciphi kwaye yonke i-{c}100 yokwehla iphuma kwisabelo sakho","Yehla ibe yi-{c}180, kuba ungumnini wesahlulo sesihlanu sesikhundla kuphela","Ihlala kwi-{c}200, kuba umhlobo wakho uthwala ukwehla kwisabelo sakhe esikhulu","Yehla ibe yi-{c}190, kuba iilahleko zahlulwa ngokwesixa ngamnye wenu asifakileyo"]}},"68":{"title":"I-Margin Yidiphozithi, Ayisiyontengo","desc":"Imali oyibekayo ayichithwa, isemngciphekweni","content":"Xa uthenga isabelo nge-{c}100, loo {c}100 ihambile kwimali yakho size isabelo sihlale kwiakhawunti yakho. Kukutshintshiselana okulula.\\n\\nI-margin ayisebenzi ngaloo ndlela. Xa uvula isikhundla se-leverage ubeka idiphozithi, kwaye loo diphozithi ayisiyontlawulo yanto. Yidiphozithi yokhuseleko echasene neelahleko zakho. Ihlala apho, itshixiwe, kwaye isikhundla siyayitya njengoko ixabiso lishukuma lichasene nawe.\\n\\nMasithi izinga lediphozithi yi-25%. Ubeka i-250 NT uze ulawule i-1,000 NT yobungozi. Jonga iakhawunti yakho:\\n\\n• Ixabiso lithe cwaka: i-250 yakho isengu-250. Kodwa imali yenkxaso-mali sele iqalile, ngoko incinci ngokuzolileyo.\\n• Ixabiso lehle nge-5%: isikhundla silahlekelwe yi-50 NT. Idiphozithi yakho ngokusebenzayo ngu-200. Imali yakho ekhululekileyo ayishukumanga. Iakhawunti yakho incinci.\\n• Ixabiso lehle nge-20%: isikhundla silahlekelwe yi-200 NT. Idiphozithi yakho yehle yaya kwi-50. Awenzanga nto. Akuthengisanga nto. Ubukele.\\n\\nMathathu amagama ahlala kuzo zonke iiscreen kule gumbi:\\n\\n🔒 I-MARGIN ESETYENZISIWEYO: yonke idiphozithi onayo ebekiweyo ngoku.\\n💰 I-EQUITY YEAKHAWUNTI: imali yakho ekhululekileyo, kunye ne-margin yakho ebekiweyo, kunye nenzuzo nelahleko yaso sonke isikhundla esivulekileyo, kususwe imali yenkxaso-mali ebizwe kude kube ngoku. Yinto iakhawunti yakho eyixabisayo ngokwenene ukuba yonke into ivalwa ngoku.\\n📊 INQANABA LE-MARGIN: i-equity yahlulwe nge-margin esetyenzisiweyo. Ngaphezu kwe-100% unomqamelo. Ngaphantsi kwe-100% imarike sele iwugqibile umqamelo yaza yaqala kwidiphozithi.\\n\\nKwaye nomthetho omnye omangalisa wonke umntu: i-margin ilinganiswa kuyo yonke iakhawunti yakho, kungekhona kwisikhundla ngasinye. Isikhundla esilahlekelwayo sitya isibambiso esixhasa esiphumelelayo. Yiyo loo nto ukuthi \\"enye intengiselwano yam ilungile\\" kungengokuzikhusela. 🔒","quiz":{"q":"Ubeka idiphozithi ye-250 NT ukuze ulawule i-1,000 NT yobungozi. Ixabiso lehla nge-8% ngelixa ungenzi nto konke konke. Kwenzeke ntoni?","options":["Akukho nto okwangoku, kuba ilahleko ibalwa kuphela xa uvala isikhundla","Utyala i-80 NT yemali eyongezelelweyo, ethathwa kwibhalansi yakho ekhululekileyo ngoko nangoko","Idiphozithi yakho ayichukunyiswanga, kuba idiphozithi yintlawulo kungekhona isibambiso","Isikhundla silahlekelwe yi-80 NT, idiphozithi yakho iyayithwala, kwaye i-equity yeakhawunti yakho incinci nge-80 NT"]}},"69":{"title":"I-Margin Call","desc":"Sisibizo esinyanzelayo, kungekhona isilumkiso","content":"I-margin call ngumzuzu apho inqanaba lakho le-margin lehla ngaphantsi kwe-100%. Ngamagama acacileyo: umqamelo wakho wenzuzo uphelile kwaye imarike sele iqale ukutya idiphozithi ngokwayo.\\n\\nNantsi indlela evakala ngayo ngokwenene, kuba inguqulelo yencwadi ishiya inxalenye ebalulekileyo.\\n\\nAyifiki ngosuku olulungileyo. Ifika xa isikhundla sele simbi, xa sele uzixelele kabini ukuba iza kubuya, naxa ungakwazi kwaphela ukwenza isigqibo esizolileyo. Asisosilumkiso esinesidima. Sisibizo esinyanzelayo: faka imali engakumbi, okanye uvale izikhundla, okanye umboneleli akwenzele oko.\\n\\nUnamanyathelo amathathu kwaye mabini kuphela kuwo angawakho.\\n\\n1️⃣ VALA into. Oku kukhulula i-margin ngoko nangoko kwaye phantse ihlala iyimpendulo elungileyo. Kukwathetha ukuvuma ukuba ubungachananga, esisona sizathu sokuba abantu bangakwenzi.\\n2️⃣ YONGEZA imali. Oku akulungisi nto. Kukuthengela indawo yokuba ungachani ixesha elide, kwisikhundla obusele usikhethe kakubi, ngemali obungacwangcisanga ukuyibeka emngciphekweni. Ukongeza imali kwi-margin call yindlela intengiselwano embi eba yinyanga embi ngayo.\\n3️⃣ UNGENZI NTO. Emva koko inyathelo lesithathu lenzeka ngaphandle kwakho, kwaye linegama.\\n\\nAbalawuli bakuthatha oku ngokungqongqo kangangokuba babhala inani emthethweni. Iinkampani eYurophu, e-UK nase-Australia kufuneka zivale ngokuzenzekelayo izikhundla zomthengi xa i-margin yakhe isihla ifika kwi-50% yaleyo bekufuneka ibekhona. Kungekhona \\"kufanele\\". KUFUNEKA. Bawubhala loo mthetho kuba xa abantu beshiywa bezigqibela ngokwabo, bakhetha ukhetho lwesithathu baza balahlekelwa ngaphezu kwaleyo bebenayo. ⚠️","quiz":{"q":"Inqanaba lakho le-margin lehle laya kwi-80% kwaye ukwi-margin call. Yeyiphi impendulo enciphisa ngokwenene umngcipheko we-liquidation endaweni yokuwulibazisa nje?","options":["Ukufaka imali engakumbi, ukuze isikhundla sibe nendawo yokuchacha","Ukuvala isikhundla, okukhulula ngoko nangoko i-margin ebisisebenzisa","Ukulinda, kuba amanqanaba e-margin adla ngokuzichachela ngokwawo","Ukuvula isikhundla sesibini kwicala elichaseneyo ukuze usicime"]}},"70":{"title":"I-Liquidation, Nexabiso Omele Ulazi Kuqala","desc":"Ixabiso kanye apho iakhawunti yakho ifika kwiqanda","content":"I-liquidation kukuvala komboneleli izikhundla zakho egameni lakho kuba idiphozithi yakho iphantse yaphela. Kuzenzekela ngokwako. Kwenzeka ngoko nangoko. Akakho ubuza uluvo lwakho, akakho ojonga ukuba ubusele uza kuchana kusini na, kwaye akukho sibheno.\\n\\nElona nani liluncedo kweli candelo liphela LIXABISO LAKHO LE-LIQUIDATION: ixabiso lokwenene, ngemali ephathekayo ({cPlural}), apho oko kwenzeka khona.\\n\\nKungekhona ipesenti. Lixabiso. Kuba ukuthi \\"unokulahlekelwa yidiphozithi yakho\\" sisivakalisi onokusinqwala uze usilibale, ngelixa ukuthi \\"u-{tech} kwi-{c}87.40 kwaye iakhawunti yakho ize\\" liyinyaniso onokuyijonga kumzobo phambi kokuba ucofe nantoni na.\\n\\nZonke iiscreen kule gumbi ziyalibonisa phambi kokuba uqinisekise, lizotywe kwisikali sexabiso esifanayo nesomzobo ukuze ubone ukuba likude kangakanani ngokwenene. Zimbini izinto oza kuziqaphela ngoko nangoko, kwaye zombini zisisifundo:\\n\\n📏 Idiphozithi enkulu ityhalela ixabiso le-liquidation kude ngakumbi. Imali yakho engakumbi ithetha ukuba ixabiso limele lihle kakhulu ngaphambi kokuba imali yakho iphele.\\n⚡ Idiphozithi encinci ilitsalela kufuphi nexabiso lanamhlanje. Ngediphozithi ye-10%, i-liquidation imalunga noshukumo lwe-10% ukusuka apho, kwaye ushukumo lwe-10% yiveki eqhelekileyo.\\n\\nEmva koko nantsi inyaniso ebuhlungu. Ixabiso le-liquidation lilapho injini ijonge ukukuvala khona, kungekhona apho uqinisekiswa ukuba uza kuphuma khona. Ukuba kufika iindaba ezimbi ebusuku ize imarike ivule kude ngaphantsi kwelo nqanaba, uvalwa nangayiphi na imali imarike eza kuyihlawula ngokwenene. Nguloo msantsa, kwaye isifundo 78 sithetha ngawo.\\n\\nYazi ixabiso lakho le-liquidation phambi kokuba uvule. Ukuba awukwazi ukulithetha ngokuvakalayo, awuyiqondi intengiselwano oza kuyenza. 💀"},"71":{"title":"Indlela Yokubuya Inzima Ngakumbi","desc":"Kutheni iilahleko kunzima ukuzibuyisa kunokuba zibonakala","content":"Iilahleko nenzuzo zivakala ngathi ziyachasana. Azichasani, kwaye imathematika ayikufuphi.\\n\\nUlahlekelwe yi-10%? Ufuna i+11% ukuze ubuye. Kuyacaphukisa, kulungile.\\nUlahlekelwe yi-50%? Ufuna i+100%. Kufuneka UPHINDE KABINI ukuze nje ulingane.\\nUlahlekelwe yi-75%? Ufuna i+300%.\\nUlahlekelwe yi-90%? Ufuna i+900%.\\n\\nIsizathu silula xa sele usibona: inzuzo ibalwa kwimfumba encinci osele ushiyeke nayo. I-100 iwela kwi-50, kwaye ukuze ukhwele usuka kwi-50 ubuyele kwi-100 loo mfumba incinci kufuneka iphinde kabini.\\n\\nNgoku yongeza i-leverage, uze uqaphele ukuba yenza ntoni ngokwenene. Ayenzi nje inzuzo yakho ikhawuleze. Ikushukumisela ezantsi kuloo tafile ngemva kwemini enye. Ukwehla kwe-12% kwisabelo, okuyiveki embi kodwa eqhelekileyo, kukubetha kwe-48% kwiakhawunti yakho ngediphozithi ye-25%. Ngoku ufuna i+92% ukuze ubuyele apho ubuqale khona, ngenxa yeveki ebingafikanga nasezindabeni.\\n\\nYiyo le nto oochwepheshe bethetha ngokukhusela imali-nkunzi phambi kokuba bathethe nangantoni na enye, nokuba kutheni ukuthi \\"ndiza kuyibuyisa\\" sisivakalisi esibiza kakhulu kurhwebo. Ukuyibuyisa kunzima ngokwamanani kunokuyilahla, ngalo lonke ixesha. ⛰️"}}`),e={ZA:{name:"Mzantsi Afrika",cName:"irandi",cPlural:"iirandi",exDesc:"yenye yamaqonga ezabelo amakhulu kwilizwekazi lonke lase-Afrika",sectorList:`⛏️ Imigodi: Anglo American, Impala Platinum. Inxulumene namaxabiso ezimbiwa ehlabathini
🏦 Iibhanki: Standard Bank, FirstRand, Capitec. Zenza kakuhle xa amazinga enzala ephezulu
📱 Itekhnoloji: Naspers, Prosus. Inxulumene neendlela zetekhnoloji ehlabathini
🛍️ Iivenkile: Shoprite, Pick n Pay. Zenza kakuhle xa abathengi benemali yokuchitha
📡 Unxibelelwano: MTN, Vodacom. Zizinzile ngakumbi, kuba abantu bahlala beyifuna i-data`,etfBasket:"iinkampani ezingama-40 ezinkulu kunazo zonke kwi-JSE",etfDesc:"Umzekelo, i-JSE Top 40 luluhlu lweenkampani ezingama-40 ezinkulu kunazo zonke ezidweliswe kwi-JSE, zilandelelaniswa ngexabiso lezabelo ezikhoyo ngokwenene ukuba zirhwetshwe.",etfList:`🇿🇦 Satrix Top 40: Iinkampani ezingama-40 ezinkulu kunazo zonke kwi-JSE. Indawo entle yokuqala.
🌍 Satrix MSCI World: Iinkampani ezivela kumazwe angama-23 aphuhlileyo, ngokuthenga kanye.
🇺🇸 Sygnia Itrix S&P 500: Iinkampani ezinkulu zaseMelika ezingama-500 ezikuluhlu lwe-S&P 500.
💡 Satrix Nasdaq 100: Iinkampani ezingama-100 ezinkulu kunazo zonke ezingezizo ezezimali kwi-Nasdaq. Zizele yitekhnoloji.`,currencyHedge:"Ezi zibekwe amaxabiso ngeedola okanye ngee-euro. Ngoko ke ukuba irandi LIPHELELWA NGAMANDLA (i-R20 kwidola ibe yi-R22), utyalo-mali lwakho lwehlabathi luxabiseka NGOKUZENZEKELAYO ngakumbi ngeerandi!",fxQuizSetup:"Irandi liphelelwa ngamandla lisuka kwi-R18 lisiya kwi-R22 xa lithelekiswa nedola",fxQuizLose:"Iyalahlekelwa lixabiso kuba uMzantsi Afrika usilela ngakumbi",fxQuizGain:"IYANYUKA ngokwerandi kuba idola nganye ithenga iirandi ezingakumbi",dcaTitle:"Ukulinganisa Iindleko ngeRandi",food:"iburger yaseWimpy"}},n={_meta:a,lessons:i,context:e};export{a as _meta,e as context,n as default,i as lessons};
